class _TrustedHtml(str):
    """Small marker for dashboard HTML assembled from escaped values."""


class _ViolinMetricDefinition(TypedDict):
    payload_key: str
    container_id: str
    title: str
    color: str


class _ViolinMetricGroupDefinition(TypedDict):
    group_key: str
    group_title: str
    group_note: str
    metrics: list[_ViolinMetricDefinition]


SelectorItems = list[dict[str, Any]]


def generate_html_dashboard(
    report_data: dict,
    output_file: str = "awr_dashboard.html",
) -> str:
    """Generate a multi-page HTML dashboard bundle and return the index path."""

    output_dir = _resolve_dashboard_output_dir(output_file)
    output_dir.mkdir(parents=True, exist_ok=True)
    pages = _build_dashboard_pages(report_data)
    for file_name, html in pages.items():
        (output_dir / file_name).write_text(html, encoding="utf-8")
    return str((output_dir / "index.html").resolve())


