def parse_ai_sections(ai_text: str) -> dict[str, str]:
    """Parse the generated AI narrative into named sections."""

    if not ai_text:
        return {name: "" for name in AI_SECTION_NAMES}

    section_map = {name: "" for name in AI_SECTION_NAMES}

    pattern = re.compile(
        r"^\s{0,3}(?:#+\s*)?" rf"({AI_SECTION_PATTERN})" r"\s*$",
        re.MULTILINE,
    )

    matches = list(pattern.finditer(ai_text))
    if not matches:
        return section_map

    for index, match in enumerate(matches):
        section_name = match.group(1)
        start = match.end()
        end = matches[index + 1].start() if index + 1 < len(matches) else len(ai_text)
        section_map[section_name] = ai_text[start:end].strip()

    return section_map


def _resolve_dashboard_output_dir(output_file: str) -> Path:
    output_path = Path(output_file)
    if output_path.suffix:
        return output_path.parent / output_path.stem
    return output_path


def _build_dashboard_pages(report_data: dict[str, Any]) -> dict[str, str]:
    """Build the full multi-page HTML product bundle."""

    title = str(report_data.get("title") or "AWR Performance Intelligence Dashboard")
    generated_at = str(report_data.get("generated_at") or datetime.utcnow().isoformat())
    screen_models = report_data.get("screen_models") or {}
    screen_4_model = screen_models.get("screen_4_historical_review") or {}
    screen_6_model = screen_models.get("screen_6_fleet_overview") or {}
    ai_sections = _normalize_ai_sections(
        parse_ai_sections(str(report_data.get("ai_generated_narrative") or ""))
    )
    decision_state = _derive_decision_state(ai_sections)
    chart_payload = _build_chart_payload(report_data)
    chart_payload["time_series_charts"] = report_data.get("time_series_charts") or {}
    violin_metric_groups = _order_violin_metric_groups(
        _build_violin_metric_groups(chart_payload["violin_panel"]),
        screen_4_model,
    )
    violin_metric_configs = _flatten_violin_metric_groups(violin_metric_groups)
    time_series_groups = _order_time_series_groups(
        _build_time_series_groups(report_data),
        screen_4_model,
    )
    parser_review_payload = _build_parser_review_payload()
    parser_governance_payload = _build_parser_governance_payload()
    governance_visibility_payload = _build_governance_visibility_payload()
    semantic_recall_visibility_payload = _build_semantic_recall_visibility_payload()
    learning_visibility_payload = _build_learning_visibility_payload(
        report_data,
        screen_6_model,
    )
    ml_explainability_visibility_payload = _build_ml_explainability_visibility_payload(
        report_data,
        screen_6_model,
    )

    pages = {
        "index.html": _build_page_html(
            page_key="home",
            page_title=title,
            report_data=report_data,
            content_html=_render_home_page(
                report_data,
                screen_models=screen_models,
            ),
            generated_at=generated_at,
        ),
        "screen_1_ingestion.html": _build_page_html(
            page_key="screen_1",
            page_title="Screen 1 - Ingestion",
            report_data=report_data,
            content_html=_render_screen_1_page(
                screen_models.get("screen_1_ingestion") or {},
                parser_review_payload=parser_review_payload,
                parser_governance_payload=parser_governance_payload,
                report_data=report_data,
            ),
            generated_at=generated_at,
        ),
        "screen_2_control.html": _build_page_html(
            page_key="screen_2",
            page_title="Screen 2 - Runtime Scope & Analysis Control",
            report_data=report_data,
            content_html=_render_screen_3_selector_page(
                screen_models.get("screen_3_history_selector") or {},
                report_data=report_data,
            ),
            generated_at=generated_at,
        ),
        "screen_3_analysis.html": _build_page_html(
            page_key="screen_3",
            page_title="Screen 3 - Diagnostic Snapshot",
            report_data=report_data,
            content_html=_render_screen_2_page(
                screen_models.get("screen_2_analysis") or {},
                ai_sections=ai_sections,
                decision_state=decision_state,
                report_data=report_data,
            ),
            generated_at=generated_at,
        ),
        "screen_4_historical_review.html": _build_page_html(
            page_key="screen_4",
            page_title="Screen 4 - Historical Review",
            report_data=report_data,
            content_html=_render_screen_4_page(
                screen_4_model,
                chart_payload=chart_payload,
                violin_metric_groups=violin_metric_groups,
                time_series_groups=time_series_groups,
                derived_scalar_metrics=report_data.get("derived_scalar_metrics") or {},
            ),
            generated_at=generated_at,
            include_chart_scripts=True,
            chart_payload=chart_payload,
            violin_metric_configs=violin_metric_configs,
            time_series_groups=time_series_groups,
        ),
        "screen_5_recommendation_action.html": _build_page_html(
            page_key="screen_5",
            page_title="Screen 5 - Recommendation Action & Outcome",
            report_data=report_data,
            content_html=_render_screen_5_page(
                screen_models.get("screen_5_recommendation_action") or {},
                ai_sections=ai_sections,
                agentic_decision=report_data.get("agentic_decision") or {},
                report_data=report_data,
            ),
            generated_at=generated_at,
        ),
        "screen_6_fleet_overview.html": _build_page_html(
            page_key="screen_6",
            page_title="Screen 6 - Learning Governance",
            report_data=report_data,
            content_html=_render_screen_6_page(
                screen_6_model,
                governance_payload=governance_visibility_payload,
                semantic_recall_payload=semantic_recall_visibility_payload,
                learning_visibility_payload=learning_visibility_payload,
                ml_explainability_visibility_payload=ml_explainability_visibility_payload,
            ),
            generated_at=generated_at,
        ),
    }
    return {
        filename: _final_dashboard_html_polish(html)
        for filename, html in pages.items()
    }


def _final_dashboard_html_polish(html: str) -> str:
    replacements = (
        (
            "CPU Insufficient data for a reliable conclusion",
            "CPU data was not sufficient in this interval to establish a reliable conclusion",
        ),
        (
            "Unavailable of DB time",
            "CPU data was not sufficient in this interval to establish a reliable conclusion",
        ),
        (
            "CPU-led evidence remains primary",
            "CPU evidence remains one of the more visible signals in the historical window, but not consistently dominant",
        ),
        (
            "governing pattern-first",
            "strongest available evidence first",
        ),
        (
            "dominant the dominant",
            "dominant",
        ),
        (
            "pattern pattern",
            "pattern",
        ),
        (
            "No deterministic recommendations were generated.",
            "No deterministic actions are recommended at this time.",
        ),
        (
            "<strong>Rarity:</strong> common pattern",
            "<strong>Rarity:</strong> Pattern appears common within the current similarity space.",
        ),
        (
            "keeping the broader window aligned to the same governing pattern",
            "keeping the broader window aligned to the same overall posture",
        ),
    )
    polished = html
    for before, after in replacements:
        polished = polished.replace(before, after)
    regex_replacements = (
        (
            r"\bthe workload remained primarily CPU-led\b",
            "CPU evidence was not sufficiently populated to confirm CPU dominance",
        ),
        (
            r"\bthe workload remained predominantly CPU-led\b",
            "CPU evidence was not sufficiently populated to confirm CPU dominance",
        ),
        (
            r"\bCPU remained the primary workload driver\b",
            "CPU dominance could not be confirmed from unavailable CPU evidence",
        ),
        (
            r"\bCPU remained the primary driver\b",
            "CPU dominance could not be confirmed from unavailable CPU evidence",
        ),
        (
            r"\baverage CPU at Unavailable\b",
            "CPU evidence was unavailable",
        ),
        (
            r"\bTop SQL concentration([^.<]*)Unavailable\b",
            "Top SQL concentration could not be evaluated from available data",
        ),
    )
    for pattern, replacement in regex_replacements:
        polished = re.sub(pattern, replacement, polished, flags=re.IGNORECASE)
    return "\n".join(line.rstrip() for line in polished.splitlines()) + "\n"


def _build_page_html(
    *,
    page_key: str,
    page_title: str,
    report_data: dict[str, Any],
    content_html: str,
    generated_at: str,
    include_chart_scripts: bool = False,
    chart_payload: dict[str, Any] | None = None,
    violin_metric_configs: list[dict[str, Any]] | None = None,
    time_series_groups: list[dict[str, Any]] | None = None,
) -> str:
    """Build one page of the multi-page dashboard experience."""

    product = _to_dict(report_data.get("product"))
    hero_title = escape(_hero_title_for_page(page_key, product))
    nav_html = _render_page_navigation(page_key)
    runtime_badge_html = _render_runtime_status_badge(report_data)
    runtime_badge_hydration_script = _render_runtime_badge_early_hydration_script()
    shell_class = "top-shell sticky-shell"
    chart_payload_json = (
        json.dumps(_chart_payload_json_safe(chart_payload or {}), indent=2)
        if include_chart_scripts
        else "{}"
    )
    chart_scripts = (
        _build_chart_runtime_javascript(
            violin_metric_configs or [],
            time_series_groups or [],
        )
        if include_chart_scripts
        else ""
    )
    chart_dependencies = (
        """
  <script id="chart-payload" type="application/json">
"""
        + chart_payload_json
        + """
  </script>
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>
"""
        if include_chart_scripts
        else ""
    )
    interactivity_script = _build_dashboard_interactivity_javascript()
    interactivity_boundary = _render_dashboard_interactivity_boundary_comment()
    gated_content_html = _wrap_downstream_evidence_gate(page_key, content_html)

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{escape(page_title)}</title>
  <style>
{_shared_page_styles()}
  </style>
</head>
<body data-dashboard-generated-at="{escape(generated_at, quote=True)}">
{interactivity_boundary}
  <div class="container">
    <div class="{shell_class}">
      <section class="hero">
        <div class="eyebrow">AWR PERFORMANCE INTELLIGENCE</div>
        <h1>{hero_title}</h1>
        {runtime_badge_html}
        {runtime_badge_hydration_script}
        <p class="hero-summary">
          Deterministic Oracle AWR intelligence delivering consistent diagnosis,
          historical context, and actionable guidance.
        </p>
        <div class="hero-meta">Generated: {escape(generated_at)}</div>
      </section>

      {nav_html}
    </div>

    {gated_content_html}

    <div class="footer">Generated at {escape(generated_at)}</div>
  </div>
{interactivity_script}
{chart_dependencies}
{chart_scripts}
</body>
</html>
"""


def _wrap_downstream_evidence_gate(page_key: str, content_html: str) -> str:
    """Hide downstream generated evidence until a current handoff is ready."""

    empty_messages = {
        "screen_3": "No diagnostic evidence is selected yet. Complete Screen 1 source intake or select a DB-backed runtime scope on Screen 2.",
        "screen_4": "No review evidence is selected yet. Complete source intake or select a runtime scope/comparison context first.",
        "screen_5": "No recommendation/action context is selected yet. Complete analysis handoff before action review.",
        "screen_6": "No learning governance context is selected yet. Complete evidence handoff before reviewing generated learning candidates.",
    }
    message = empty_messages.get(page_key)
    if not message:
        return content_html
    return f"""
    <section class="card prominent dashboard-evidence-empty-state"
             data-dashboard-evidence-gate-empty="true"
             data-dashboard-evidence-page="{escape(page_key, quote=True)}">
      <div class="section-kicker">Evidence Readiness</div>
      <h2>Evidence Handoff Required</h2>
      <p class="meta">{escape(message)}</p>
    </section>
    <div data-dashboard-evidence-gated-content="true"
         data-dashboard-evidence-page="{escape(page_key, quote=True)}"
         hidden>
      {content_html}
    </div>
    """


def _render_dashboard_interactivity_boundary_comment() -> str:
    """Return the Phase 7H.1 read-only interactivity boundary marker."""

    state_keys = ", ".join(DASHBOARD_INTERACTIVITY_STATE_KEYS)
    hooks = ", ".join(DASHBOARD_INTERACTIVITY_SELECTABLE_ATTRIBUTES)
    return f"""  <!--
    Dashboard Interactivity Foundation (Phase 7H.1).
    Cross-Screen Selection Propagation (Phase 7H.8).
    Browser-side selection state is not authoritative truth.
    Browser actions may submit governed workflow requests through the workflow service.
    Browser actions do not directly mutate parser output, governance truth,
    Phase 4I, diagnostics, scoring, recommendations, or runtime eligibility.
    Does not change diagnostic truth. Does not change historical truth.
    Does not change recommendation truth. Does not change parser output.
    Does not change governance state. Does not change candidate status.
    Does not approve or activate learning candidates.
    Does not activate learning candidates. No approval controls. No runtime activation.
    Semantic context remains reviewer-assist only.
    Learning candidates remain proposal/review context only.
    Supported state keys: {state_keys}.
    Future selectable metadata hooks: {hooks}.
  -->"""


