def _render_runtime_status_badge(report_data: dict[str, Any]) -> str:
    status = _runtime_status_from_report(report_data)
    mode_class = (
        "error"
        if status["db_connectivity"].upper() == "FAILED"
        else _status_pill_class(status["runtime_mode"])
    )
    return f"""
      <div class="runtime-badge" data-dashboard-runtime-badge="true">
        <span class="status-pill {escape(mode_class)}">{escape(status["runtime_mode"])}</span>
        <div class="runtime-meta">
          {_render_runtime_state_line(report_data, status)}
        </div>
      </div>
    """


def _render_runtime_badge_early_hydration_script() -> str:
    """Return a tiny inline badge hydrator that runs before the main JS bundle."""

    storage_key_json = json.dumps(DASHBOARD_INTERACTIVITY_STORAGE_KEY)
    return """
        <script>
          (function () {
            'use strict';
            const DASHBOARD_STORAGE_KEY = __DASHBOARD_STORAGE_KEY__;
            const SCREEN3_RUNTIME_OPTIONS_CACHE_KEY = 'screen3RuntimeOptionsCache';
            const SCREEN3_RUNTIME_OPTIONS_CACHE_VERSION = 'screen3-runtime-options-v1';
            const badge = document.querySelector('[data-dashboard-runtime-badge="true"]');
            const workflowStatus = document.querySelector('[data-dashboard-runtime-workflow-status="true"]');

            function safeRuntimeBadgeValue(value) {
              if (value === undefined || value === null) {
                return '';
              }
              return String(value).replace(/[<>]/g, '').trim().slice(0, 256);
            }

            function runtimeBadgeStateClass(value) {
              const normalized = safeRuntimeBadgeValue(value).toLowerCase();
              if (
                normalized === 'connected' ||
                normalized === 'available' ||
                normalized === 'active' ||
                normalized === 'accepted' ||
                normalized === 'loaded'
              ) {
                return 'state-pass';
              }
              if (
                normalized.indexOf('error') >= 0 ||
                normalized.indexOf('failed') >= 0 ||
                normalized.indexOf('unavailable') >= 0
              ) {
                return 'state-error';
              }
              if (
                normalized.indexOf('warning') >= 0 ||
                normalized.indexOf('degraded') >= 0 ||
                normalized.indexOf('partial') >= 0
              ) {
                return 'state-warning';
              }
              return 'state-muted';
            }

            function readStoredWorkflowStatus() {
              try {
                const rawState = window.localStorage.getItem(DASHBOARD_STORAGE_KEY);
                if (rawState) {
                  const dashboardState = JSON.parse(rawState);
                  const storedStatus = safeRuntimeBadgeValue(dashboardState && dashboardState.screen3LiveServiceStatus);
                  if (storedStatus) {
                    return storedStatus;
                  }
                }
              } catch (error) {
                // Badge hydration is continuity-only; invalid browser state is ignored.
              }
              try {
                const rawCache = window.localStorage.getItem(SCREEN3_RUNTIME_OPTIONS_CACHE_KEY);
                if (rawCache) {
                  const cache = JSON.parse(rawCache);
                  if (
                    cache &&
                    cache.cache_version === SCREEN3_RUNTIME_OPTIONS_CACHE_VERSION &&
                    cache.options &&
                    typeof cache.options === 'object'
                  ) {
                    return safeRuntimeBadgeValue(cache.service_status || 'Available');
                  }
                }
              } catch (error) {
                // Cache is not authoritative truth; failed cache reads leave the neutral default.
              }
              return '';
            }

            function applyWorkflowStatus(value) {
              if (!workflowStatus) {
                return;
              }
              const nextValue = (
                safeRuntimeBadgeValue(value) ||
                safeRuntimeBadgeValue(workflowStatus.getAttribute('data-empty-label')) ||
                'Check with Load Options'
              );
              workflowStatus.textContent = nextValue;
              workflowStatus.classList.remove('state-pass', 'state-warning', 'state-error', 'state-low', 'state-accent', 'state-muted');
              workflowStatus.classList.add(runtimeBadgeStateClass(nextValue));
              workflowStatus.setAttribute('data-dashboard-state-value', nextValue);
            }

            applyWorkflowStatus(readStoredWorkflowStatus());
            if (badge) {
              badge.classList.add('runtime-badge-hydrated');
              badge.setAttribute('data-runtime-badge-hydrated', 'true');
            }
          }());
        </script>
    """.replace("__DASHBOARD_STORAGE_KEY__", storage_key_json)


def _render_runtime_state_line(
    report_data: dict[str, Any],
    status: dict[str, str],
) -> str:
    memory_state, memory_class = _memory_runtime_state(report_data)
    db_state = status["db_connectivity"]
    similarity_state = status["similarity_status"]
    return (
        '<span class="runtime-state-line runtime-state-pills">'
        '<span class="runtime-mini-pill" data-runtime-badge-kind="build-db" title="Generated at build time DB status">Build DB: '
        f'<strong class="{escape(_db_runtime_state_class(db_state))}">{escape(db_state)}</strong>'
        "</span>"
        '<span class="runtime-mini-pill" data-runtime-badge-kind="workflow" title="Local dashboard workflow service status. Click Load available runtime options to check the service, validate the runtime-control options route, and verify the DB-backed runtime option path. This is separate from build-time DB status.">Workflow Service: '
        '<strong class="state-muted" data-dashboard-state-input="true" data-dashboard-state-status-class="runtime" '
        'data-dashboard-runtime-workflow-status="true" '
        'data-dashboard-state-key="screen3LiveServiceStatus" '
        'data-empty-label="Check with Load Options">Check with Load Options</strong>'
        "</span>"
        '<span class="runtime-mini-pill" data-runtime-badge-kind="similarity">Similarity: '
        f'<strong class="{escape(_similarity_runtime_state_class(similarity_state))}">{escape(similarity_state)}</strong>'
        "</span>"
        '<span class="runtime-mini-pill" data-runtime-badge-kind="memory">Memory: '
        f'<strong class="{escape(memory_class)}">{escape(memory_state)}</strong>'
        "</span>"
        "</span>"
    )


def _memory_runtime_state(report_data: dict[str, Any]) -> tuple[str, str]:
    memory_runtime = _to_dict(report_data.get("memory_runtime"))
    state = str(memory_runtime.get("state") or "").strip()
    if state.lower() == "off":
        return "Off", _runtime_state_class("Off", "memory")
    if state.lower() == "error":
        return "Error", _runtime_state_class("Error", "memory")
    enabled = memory_runtime.get("enabled")
    success = memory_runtime.get("success")
    if enabled is False:
        return "Off", _runtime_state_class("Off", "memory")
    if success is False:
        return "Error", _runtime_state_class("Error", "memory")
    return "Active", _runtime_state_class("Active", "memory")


def _db_runtime_state_class(state: str) -> str:
    return _runtime_state_class(state, "db")


def _similarity_runtime_state_class(state: str) -> str:
    return _runtime_state_class(state, "similarity")


def _runtime_state_class(value: Any, context: str | None = None) -> str:
    semantic = _status_semantic_class(value, context)
    if semantic == "pass":
        return "state-pass"
    if semantic == "warning":
        return "state-warning"
    if semantic == "error":
        return "state-error"
    if semantic == "low":
        return "state-low"
    return "state-muted"


def _runtime_status_from_report(report_data: dict[str, Any]) -> dict[str, str]:
    ingestion_context = _to_dict(report_data.get("ingestion_context"))
    db_ingestion = _to_dict(ingestion_context.get("db_ingestion"))
    if not db_ingestion:
        screen_1 = _to_dict(
            _to_dict(report_data.get("screen_models")).get("screen_1_ingestion")
        )
        db_ingestion = _to_dict(screen_1.get("db_ingestion"))
    summary = _to_dict(db_ingestion.get("summary"))
    db_connectivity = _clean_runtime_status_text(
        summary.get("db_connectivity"),
        default="Not checked",
    )
    db_ready = _truthy_status(summary.get("db_similarity_ready"))
    connected = db_connectivity.strip().lower() == "connected"
    if connected and db_ready:
        runtime_mode = "FULL DB MODE"
    elif connected:
        runtime_mode = "DB CONNECTED - SIMILARITY UNAVAILABLE"
    else:
        runtime_mode = "GENERATED DB WARNING"
    similarity_status = "Available" if connected and db_ready else "Unavailable"
    display_db_connectivity = "Connected" if connected else "Failed"
    return {
        "runtime_mode": runtime_mode,
        "db_connectivity": display_db_connectivity,
        "similarity_status": similarity_status,
    }


def _build_parser_review_payload() -> dict[str, Any]:
    payload: dict[str, Any] = {
        "available": False,
        "summary": {
            "TOTAL": 0,
            "NEW": 0,
            "REVIEWED": 0,
            "CLASSIFIED": 0,
            "IGNORED": 0,
        },
        "pattern_summary": [],
        "recent_unknowns": [],
        "error": None,
    }
    try:
        connection = _dashboard_memory_connection()
        try:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT REVIEW_STATUS, COUNT(*)
                      FROM AWR_UNKNOWN_SIGNAL_HISTORY
                     GROUP BY REVIEW_STATUS
                    """
                )
                for status, count in cursor.fetchall():
                    status_key = _memory_status_key(status) or "NEW"
                    row_count = int(count or 0)
                    payload["summary"]["TOTAL"] += row_count
                    if status_key in payload["summary"]:
                        payload["summary"][status_key] += row_count

                cursor.execute(
                    """
                    SELECT
                      UNKNOWN_SIGNAL_ID,
                      SECTION_NAME,
                      UNKNOWN_TYPE,
                      DETECTION_REASON,
                      REVIEW_STATUS,
                      REVIEW_CLASSIFICATION
                    FROM AWR_UNKNOWN_SIGNAL_HISTORY
                    ORDER BY LAST_SEEN_TIMESTAMP DESC NULLS LAST
                    """
                )
                payload["pattern_summary"] = _group_unknown_signal_patterns(
                    [
                        {
                            "unknown_signal_id": row[0],
                            "section_name": row[1],
                            "unknown_type": row[2],
                            "detection_reason": row[3],
                            "review_status": row[4],
                            "review_classification": row[5],
                        }
                        for row in cursor.fetchall()
                    ]
                )

                cursor.execute(
                    """
                    SELECT
                      UNKNOWN_SIGNAL_ID,
                      SECTION_NAME,
                      UNKNOWN_TYPE,
                      DETECTION_REASON,
                      REVIEW_STATUS,
                      REVIEW_CLASSIFICATION,
                      REVIEWED_BY,
                      REVIEWED_AT
                    FROM AWR_UNKNOWN_SIGNAL_HISTORY
                    ORDER BY UNKNOWN_SIGNAL_ID ASC
                    """
                )
                payload["recent_unknowns"] = [
                    {
                        "unknown_signal_id": row[0],
                        "section_name": row[1],
                        "unknown_type": row[2],
                        "detection_reason": row[3],
                        "review_status": row[4],
                        "review_classification": row[5],
                        "reviewed_by": row[6],
                        "reviewed_at": row[7],
                    }
                    for row in cursor.fetchall()
                ]
        finally:
            connection.close()
        payload["available"] = True
        return payload
    except Exception as exc:  # noqa: BLE001
        payload["error"] = f"{type(exc).__name__}: {exc}"
        return payload


def _build_parser_governance_payload() -> dict[str, Any]:
    payload: dict[str, Any] = {
        "available": False,
        "items": [],
        "field_mapping_candidates": [],
        "knowledge_requests": [],
        "knowledge_artifacts": [],
        "error": None,
    }
    try:
        connection = _dashboard_memory_connection()
        try:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT
                      u.UNKNOWN_SIGNAL_ID,
                      u.PARSER_CONTEXT,
                      u.REVIEW_STATUS,
                      u.SOURCE_FILE_NAME,
                      u.FIRST_SEEN_TIMESTAMP,
                      u.LAST_SEEN_TIMESTAMP,
                      (
                        SELECT MAX(m.APPROVAL_STATUS)
                          FROM AWR_PARSER_MAPPING_CANDIDATE m
                         WHERE m.UNKNOWN_SIGNAL_ID = u.UNKNOWN_SIGNAL_ID
                      ) AS APPROVAL_STATUS
                    FROM AWR_UNKNOWN_SIGNAL_HISTORY u
                    ORDER BY u.UNKNOWN_SIGNAL_ID ASC
                    """
                )
                items = []
                for row in cursor.fetchall():
                    parser_context = _memory_json_context(row[1])
                    items.append(
                        {
                            "unknown_signal_id": row[0],
                            "parser_stage": parser_context.get("parser_stage"),
                            "classification_hint": parser_context.get("classification_hint"),
                            "review_status": row[2],
                            "approval_status": row[6],
                            "source_file": row[3] or parser_context.get("source_file_path"),
                            "first_seen_timestamp": row[4],
                            "last_seen_timestamp": row[5],
                        }
                    )
                payload["items"] = items
                cursor.execute(
                    """
                    SELECT
                      m.MAPPING_CANDIDATE_ID,
                      m.UNKNOWN_SIGNAL_ID,
                      m.PROPOSED_SECTION_TYPE,
                      m.PROPOSED_DOMAIN,
                      m.PROPOSED_METRIC_NAME,
                      m.PROPOSED_MAPPING_JSON,
                      m.APPROVAL_STATUS,
                      u.SECTION_NAME,
                      u.RAW_SAMPLE_TEXT,
                      u.SOURCE_FILE_NAME,
                      u.FREQUENCY_COUNT,
                      u.REVIEW_STATUS
                    FROM AWR_PARSER_MAPPING_CANDIDATE m
                    JOIN AWR_UNKNOWN_SIGNAL_HISTORY u
                      ON u.UNKNOWN_SIGNAL_ID = m.UNKNOWN_SIGNAL_ID
                    ORDER BY m.MAPPING_CANDIDATE_ID ASC
                    """
                )
                field_candidates = []
                for row in cursor.fetchall():
                    mapping_context = _memory_json_context(row[5])
                    proposed_metric = row[4] or mapping_context.get("metric_name")
                    source_section = row[7] or row[2] or mapping_context.get("section")
                    proposed_field = (
                        mapping_context.get("normalized_field_name")
                        or mapping_context.get("target_field")
                        or mapping_context.get("field_name")
                        or proposed_metric
                    )
                    candidate_name = (
                        mapping_context.get("candidate_field_name")
                        or mapping_context.get("source_field")
                        or proposed_metric
                        or source_section
                    )
                    if not _has_display_value(candidate_name):
                        continue
                    field_candidates.append(
                        {
                            "candidate_id": row[0],
                            "unknown_signal_id": row[1],
                            "candidate_field_name": candidate_name,
                            "source_awr_section": source_section,
                            "sample_value": (
                                mapping_context.get("sample_value")
                                or mapping_context.get("example_value")
                                or str(row[8] or "")[:140]
                            ),
                            "source_file": row[9],
                            "report_count": row[10] or 1,
                            "occurrence_count": row[10] or 1,
                            "proposed_normalized_field_name": proposed_field,
                            "proposed_parser_target": mapping_context.get("parser_target")
                            or row[3]
                            or row[2],
                            "proposed_data_type": mapping_context.get("data_type")
                            or mapping_context.get("type")
                            or "Review required",
                            "confidence_status": row[6] or row[11] or "Review needed",
                            "recommended_action": "Review governed parser mapping candidate",
                        }
                    )
                payload["field_mapping_candidates"] = field_candidates
                cursor.execute(
                    """
                    SELECT
                      REQUEST_ID,
                      SOURCE_TYPE,
                      SOURCE_ID,
                      CANDIDATE_CLASSIFICATION,
                      CANDIDATE_SUMMARY,
                      APPROVAL_STATUS,
                      APPROVED_BY,
                      APPROVED_AT,
                      CREATED_AT
                    FROM AWR_KNOWLEDGE_UPDATE_REQUEST
                    ORDER BY CREATED_AT DESC NULLS LAST
                    FETCH FIRST 5 ROWS ONLY
                    """
                )
                payload["knowledge_requests"] = [
                    {
                        "request_id": row[0],
                        "source_type": row[1],
                        "source_id": row[2],
                        "candidate_classification": row[3],
                        "candidate_summary": row[4],
                        "approval_status": row[5],
                        "approved_by": row[6],
                        "approved_at": row[7],
                        "created_at": row[8],
                    }
                    for row in cursor.fetchall()
                ]
                cursor.execute(
                    """
                    SELECT
                      ARTIFACT_ID,
                      REQUEST_ID,
                      SOURCE_TYPE,
                      SOURCE_ID,
                      ARTIFACT_TYPE,
                      ARTIFACT_CLASSIFICATION,
                      ARTIFACT_SUMMARY,
                      ACTIVATION_STATUS,
                      CREATED_AT
                    FROM AWR_KNOWLEDGE_ARTIFACT
                    ORDER BY CREATED_AT DESC NULLS LAST
                    FETCH FIRST 5 ROWS ONLY
                    """
                )
                payload["knowledge_artifacts"] = [
                    {
                        "artifact_id": row[0],
                        "request_id": row[1],
                        "source_type": row[2],
                        "source_id": row[3],
                        "artifact_type": row[4],
                        "artifact_classification": row[5],
                        "artifact_summary": row[6],
                        "activation_status": row[7],
                        "created_at": row[8],
                    }
                    for row in cursor.fetchall()
                ]
        finally:
            connection.close()
        payload["available"] = True
        return payload
    except Exception as exc:  # noqa: BLE001
        payload["error"] = f"{type(exc).__name__}: {exc}"
        return payload


def _build_governance_visibility_payload(limit: int = 5) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "available": False,
        "unknown_signal_summary": {
            "TOTAL": 0,
            "PENDING_REVIEW": 0,
            "APPROVED": 0,
            "REJECTED": 0,
        },
        "approval_summary": {
            "PENDING": 0,
            "APPROVED": 0,
            "REJECTED": 0,
            "NEEDS_REVIEW": 0,
            "NEEDS_REVISION": 0,
        },
        "artifact_summary": {
            "INACTIVE": 0,
            "READY": 0,
            "ACTIVE": 0,
            "TOTAL": 0,
            "MATERIALIZED": 0,
        },
        "workflow_summary": {
            "NEW": 0,
            "PENDING": 0,
            "APPROVED": 0,
            "REJECTED": 0,
            "NEEDS_REVISION": 0,
        },
        "linkage": [],
        "error": None,
    }
    try:
        connection = _dashboard_memory_connection()
        try:
            with connection.cursor() as cursor:
                request_id_column = _dashboard_table_id_column(
                    cursor,
                    "AWR_KNOWLEDGE_UPDATE_REQUEST",
                    ("REQUEST_ID", "KNOWLEDGE_UPDATE_ID"),
                )
                cursor.execute(
                    """
                    SELECT REVIEW_STATUS, COUNT(*)
                      FROM AWR_UNKNOWN_SIGNAL_HISTORY
                     GROUP BY REVIEW_STATUS
                    """
                )
                for status, count in cursor.fetchall():
                    status_key = _memory_status_key(status) or "NEW"
                    row_count = int(count or 0)
                    payload["unknown_signal_summary"]["TOTAL"] += row_count
                    if status_key == "NEW":
                        payload["unknown_signal_summary"]["PENDING_REVIEW"] += row_count
                        payload["workflow_summary"]["NEW"] += row_count

                cursor.execute(
                    """
                    SELECT APPROVAL_STATUS, COUNT(*)
                      FROM AWR_PARSER_MAPPING_CANDIDATE
                     GROUP BY APPROVAL_STATUS
                    """
                )
                for status, count in cursor.fetchall():
                    status_key = _memory_status_key(status)
                    row_count = int(count or 0)
                    if status_key == "APPROVED":
                        payload["unknown_signal_summary"]["APPROVED"] += row_count
                    elif status_key == "REJECTED":
                        payload["unknown_signal_summary"]["REJECTED"] += row_count

                cursor.execute(
                    """
                    SELECT APPROVAL_STATUS, COUNT(*)
                      FROM AWR_KNOWLEDGE_UPDATE_REQUEST
                     GROUP BY APPROVAL_STATUS
                    """
                )
                for status, count in cursor.fetchall():
                    status_key = _memory_status_key(status) or "PENDING"
                    if status_key == "NEEDS_REVIEW":
                        status_key = "NEEDS_REVISION"
                    row_count = int(count or 0)
                    if status_key in payload["approval_summary"]:
                        payload["approval_summary"][status_key] += row_count
                    if status_key in payload["workflow_summary"]:
                        payload["workflow_summary"][status_key] += row_count

                cursor.execute(
                    """
                    SELECT ACTIVATION_STATUS, COUNT(*)
                      FROM AWR_KNOWLEDGE_ARTIFACT
                     GROUP BY ACTIVATION_STATUS
                    """
                )
                for status, count in cursor.fetchall():
                    status_key = _memory_status_key(status) or "INACTIVE"
                    row_count = int(count or 0)
                    payload["artifact_summary"]["TOTAL"] += row_count
                    payload["artifact_summary"]["MATERIALIZED"] += row_count
                    if status_key in payload["artifact_summary"]:
                        payload["artifact_summary"][status_key] += row_count

                payload["workflow_summary"]["PENDING"] = int(
                    payload["approval_summary"].get("PENDING") or 0
                )
                payload["workflow_summary"]["APPROVED"] = int(
                    payload["approval_summary"].get("APPROVED") or 0
                ) + int(payload["unknown_signal_summary"].get("APPROVED") or 0)
                payload["workflow_summary"]["REJECTED"] = int(
                    payload["approval_summary"].get("REJECTED") or 0
                ) + int(payload["unknown_signal_summary"].get("REJECTED") or 0)

                cursor.execute(
                    f"""
                    SELECT
                      r.{request_id_column},
                      r.SOURCE_TYPE,
                      r.SOURCE_ID,
                      r.RUN_HISTORY_ID,
                      r.APPROVAL_STATUS,
                      a.ARTIFACT_ID,
                      a.ARTIFACT_CLASSIFICATION,
                      a.ACTIVATION_STATUS
                    FROM AWR_KNOWLEDGE_UPDATE_REQUEST r
                    LEFT JOIN AWR_KNOWLEDGE_ARTIFACT a
                      ON a.REQUEST_ID = r.{request_id_column}
                    ORDER BY r.CREATED_AT DESC NULLS LAST
                    FETCH FIRST {max(1, min(int(limit or 5), 5))} ROWS ONLY
                    """
                )
                payload["linkage"] = [
                    {
                        "request_id": row[0],
                        "source_type": row[1],
                        "source_id": row[2],
                        "run_history_id": row[3],
                        "approval_status": row[4],
                        "artifact_id": row[5],
                        "artifact_classification": row[6],
                        "activation_status": row[7],
                    }
                    for row in cursor.fetchall()
                ]
        finally:
            connection.close()
        payload["available"] = True
        return payload
    except Exception as exc:  # noqa: BLE001
        payload["error"] = f"{type(exc).__name__}: {exc}"
        return payload


