def _build_screen3_reanalysis_request_preview_model(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
    control_center: dict[str, list[dict[str, Any]]],
) -> dict[str, str]:
    header = _to_dict(screen_model.get("header"))
    metadata = _to_dict(report_data.get("metadata"))
    analysis_context = _to_dict(report_data.get("analysis_context"))

    def first_selector_value(group_key: str) -> str | None:
        for item in control_center.get(group_key, []):
            value = _first_display_value(item.get("value"))
            if value:
                return value
        return None

    selected_awr = first_selector_value("awr_run")
    selected_run = _first_display_value(
        report_data.get("run_history_id"),
        report_data.get("run_id"),
        analysis_context.get("run_history_id"),
        analysis_context.get("run_id"),
    )
    selected_database = _first_display_value(
        first_selector_value("database_system"),
        header.get("db_name"),
        metadata.get("db_name"),
    )
    selected_system = _first_display_value(
        header.get("host_name"),
        metadata.get("host_name"),
        header.get("instance_name"),
        metadata.get("instance_name"),
    )

    return {
        "current_awr_run_context": _join_compact_values([selected_awr, selected_run])
        or "Current generated run context unavailable",
        "current_database_system": _join_compact_values([selected_database, selected_system])
        or "Current database/system context unavailable",
        "current_snapshot_window": first_selector_value("snapshot") or "Current snapshot/window unavailable",
        "available_comparison_baseline": first_selector_value("comparison_baseline")
        or "No comparison baseline available in current generated context",
        "available_issue_domain_filter": first_selector_value("domain") or "No issue-domain filter option available",
        "available_severity_status_filter": first_selector_value("severity")
        or "No severity/status filter option available",
        "source_context_readiness": "Ready when Index source handoff state is present; otherwise missing source selection",
        "source_metadata_readiness": "Validated by backend after governed source handoff",
        "existing_run_readiness": "Ready when an existing-run reference is returned by the workflow service",
        "object_storage_readiness": "Object Storage source selection and validation are handled on Screen 1; full load/analyze requires server-side gates",
        "backend_service_readiness": "Dashboard workflow service must be running for interactive actions",
        "db_persistence_readiness": "DB-backed workflow records are authoritative when configured; JSON audit fallback remains context",
        "execution_mode_boundary": "Approved local backend execution boundary",
        "runner_readiness": "Execution blocked until a safe injected deterministic runner is configured",
        "artifact_lifecycle_readiness": "Execution blocked until new run/output/artifact lifecycle is connected",
        "comparison_readiness": "Build Comparison is blocked unless structured comparison inputs are ready",
        "object_storage_full_load_gates": "Full load-to-analysis blocked until server-side client, load, parse, ingest, analyze, and artifact gates are connected",
        "requested_action_placeholder": "Analyze Selection, Re-run Analysis, Build Comparison, Load / Prepare External Target",
        "validation_blocked_status": "Request/readiness persistence active; execution blocks when runner/client/artifact gates are missing",
    }


def _build_screen3_control_center_model(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    """Build read-only Screen 3 selector cards without changing runtime truth."""

    header = _to_dict(screen_model.get("header"))
    selection_controls = _to_dict(screen_model.get("selection_controls"))
    scope_selection = _to_dict(screen_model.get("scope_selection"))
    timeframe_selection = _to_dict(screen_model.get("timeframe_selection"))
    review_mode = _to_dict(screen_model.get("review_mode"))
    screen_models = _to_dict(report_data.get("screen_models"))
    screen_2 = _to_dict(screen_models.get("screen_2_analysis"))
    metadata = _to_dict(report_data.get("metadata"))
    analysis_context = _to_dict(report_data.get("analysis_context"))
    comparison_context = _to_dict(report_data.get("comparison_context"))
    normalized_decision = _to_dict(screen_2.get("normalized_decision"))
    decision_summary = _to_dict(screen_2.get("decision_summary"))
    agentic_decision = _to_dict(report_data.get("agentic_decision"))
    decision = _to_dict(report_data.get("decision"))

    awr_run: SelectorItems = []
    _append_screen3_selector_item(
        awr_run,
        label="Current AWR",
        value=_first_display_value(
            metadata.get("awr_id"),
            report_data.get("awr_id"),
            agentic_decision.get("awr_id"),
            decision.get("awr_id"),
        ),
        select_type="awr",
        state_key="selectedAwr",
        note="Current generated dashboard context. Selection is stored locally for exploration only.",
    )
    _append_screen3_selector_item(
        awr_run,
        label="Current Run",
        value=_first_display_value(
            report_data.get("run_history_id"),
            report_data.get("run_id"),
            analysis_context.get("run_history_id"),
            analysis_context.get("run_id"),
        ),
        select_type="run",
        state_key="selectedRun",
        note="Run selection is browser-side only and does not re-run analysis.",
    )

    database_system: SelectorItems = []
    _append_screen3_selector_item(
        database_system,
        label="Database",
        value=_first_display_value(
            selection_controls.get("db_dbid"),
            _format_scope_label_value(
                header.get("db_name") or metadata.get("db_name"),
                header.get("dbid") or metadata.get("dbid"),
                fallback=scope_selection.get("active_scope"),
            ),
        ),
        select_type="db",
        state_key="selectedDb",
        note="Database selection does not change parser output or scoring.",
    )
    _append_screen3_selector_item(
        database_system,
        label="System",
        value=_first_display_value(
            selection_controls.get("host_instance"),
            _join_compact_values(
                [
                    header.get("host_name") or metadata.get("host_name"),
                    header.get("instance_name") or metadata.get("instance_name"),
                ]
            ),
        ),
        select_type="system",
        state_key="selectedSystem",
        note="System selection is a local exploration marker only.",
    )

    snapshot: SelectorItems = []
    snapshot_labels = [
        _display_value(label)
        for label in list(report_data.get("snapshot_labels") or [])[:8]
        if _has_display_value(label)
    ]
    for label in snapshot_labels:
        _append_screen3_selector_item(
            snapshot,
            label="Snapshot",
            value=label,
            select_type="snapshot",
            state_key="selectedSnapshot",
            note="Snapshot selection does not change deterministic evidence.",
        )
    if not snapshot:
        for label, value in (
            ("Latest interval", selection_controls.get("latest_interval") or timeframe_selection.get("window_a")),
            ("Worst interval", selection_controls.get("worst_interval") or timeframe_selection.get("window_b")),
            ("Snapshot window", selection_controls.get("snapshot_window") or timeframe_selection.get("comparison_window")),
        ):
            _append_screen3_selector_item(
                snapshot,
                label=label,
                value=_first_display_value(value),
                select_type="snapshot",
                state_key="selectedSnapshot",
                note="Snapshot selection is stored locally for exploration only.",
            )

    primary_domain = _screen3_domain_key(
        _first_display_value(
            normalized_decision.get("primary_issue"),
            decision_summary.get("primary_issue"),
            decision.get("primary_issue"),
            decision.get("primary_domain"),
        )
    )
    domain = [
        {
            "label": domain_name,
            "value": domain_name,
            "select_type": "domain",
            "state_key": "selectedDomain",
            "note": "Exploratory domain selection only; does not change primary issue.",
            "active": False,
            "domain": domain_name,
        }
        for domain_name in SCREEN3_CONTROL_CENTER_DOMAINS
    ]

    severity: SelectorItems = []
    _append_screen3_selector_item(
        severity,
        label="Current status",
        value=_first_display_value(
            normalized_decision.get("overall_status"),
            decision_summary.get("overall_status"),
            agentic_decision.get("overall_status"),
            decision.get("overall_status"),
            decision.get("risk_level"),
            decision.get("status"),
        ),
        select_type="severity",
        state_key="selectedSeverity",
        note="Status selection does not change severity.",
    )
    _append_screen3_selector_item(
        severity,
        label="Display severity",
        value=_first_display_value(
            normalized_decision.get("display_severity_label"),
            decision_summary.get("display_severity_label"),
            normalized_decision.get("severity_score"),
            decision_summary.get("severity_score"),
            agentic_decision.get("severity_score"),
            decision.get("severity_score"),
        ),
        select_type="severity",
        state_key="selectedSeverity",
        note="Severity selection is not an authoritative severity override.",
    )

    comparison_baseline: SelectorItems = []
    for label, value in (
        ("Comparison window", timeframe_selection.get("comparison_window") or comparison_context.get("comparison_window")),
        ("Latest interval baseline", timeframe_selection.get("window_a") or comparison_context.get("latest_snapshot_summary")),
        ("Worst interval baseline", timeframe_selection.get("window_b") or comparison_context.get("worst_snapshot_summary")),
        ("Latest vs prior", timeframe_selection.get("latest_vs_prior") or comparison_context.get("latest_vs_trend")),
        ("Comparison mode", timeframe_selection.get("comparison_mode") or selection_controls.get("active_comparison_mode")),
    ):
        _append_screen3_selector_item(
            comparison_baseline,
            label=label,
            value=_first_display_value(value),
            select_type="comparisonBaseline",
            state_key="selectedComparisonBaseline",
            note="Baseline selection records local comparison intent only until submitted through a governed action.",
        )

    fleet_context: SelectorItems = []
    for option in list(scope_selection.get("options") or []) + list(selection_controls.get("comparison_modes") or []):
        option_text = _first_display_value(option)
        if not option_text:
            continue
        normalized = option_text.lower()
        if "fleet" not in normalized and "similar" not in normalized and "global" not in normalized:
            continue
        _append_screen3_selector_item(
            fleet_context,
            label="Comparison context",
            value=option_text,
            select_type="fleetGroup",
            state_key="selectedFleetGroup",
            note="Fleet context is exploratory and does not create validated fleet truth.",
        )

    if not fleet_context and "fleet" in [str(mode).lower() for mode in review_mode.get("options") or []]:
        _append_screen3_selector_item(
            fleet_context,
            label="Review mode",
            value="fleet",
            select_type="fleetGroup",
            state_key="selectedFleetGroup",
            note="Fleet review mode is read-only context only.",
        )

    return {
        "awr_run": awr_run,
        "database_system": database_system,
        "snapshot": snapshot,
        "domain": domain,
        "severity": severity,
        "comparison_baseline": comparison_baseline,
        "fleet_context": fleet_context,
    }


def _append_screen3_selector_item(
    items: list[dict[str, Any]],
    *,
    label: str,
    value: Any,
    select_type: str,
    state_key: str,
    note: str,
) -> None:
    value_text = _first_display_value(value)
    if not value_text:
        return
    item = {
        "label": label,
        "value": value_text,
        "select_type": select_type,
        "state_key": state_key,
        "note": note,
    }
    if select_type == "domain":
        item["domain"] = value_text
    items.append(item)


def _render_screen3_selector_group(
    items: list[dict[str, Any]],
    empty_message: str,
) -> str:
    if not items:
        return _render_empty_item(empty_message)
    cards = "".join(_render_screen3_selector_card(item) for item in items)
    return f'<div class="screen3-selector-grid">{cards}</div>'


def _render_screen3_selector_card(item: dict[str, Any]) -> str:
    label = _display_value(item.get("label"))
    value = _display_value(item.get("value"))
    select_type = str(item.get("select_type") or "").strip()
    state_key = str(item.get("state_key") or "").strip()
    note = _display_value(item.get("note"))
    domain_attr = ""
    if _has_display_value(item.get("domain")):
        domain_attr = f' data-dashboard-select-domain="{escape(_display_value(item.get("domain")), quote=True)}"'
    active_class = " active" if bool(item.get("active")) else ""
    return f"""
      <article
        class="screen3-selector-card{active_class}"
        tabindex="0"
        aria-selected="false"
        data-dashboard-selectable="true"
        data-dashboard-select-type="{escape(select_type, quote=True)}"
        data-dashboard-select-key="{escape(state_key, quote=True)}"
        data-dashboard-select-id="{escape(value, quote=True)}"
        data-dashboard-filter-key="{escape(state_key, quote=True)}"
        data-dashboard-filter-value="{escape(value, quote=True)}"{domain_attr}
      >
        <strong>{escape(label)}</strong>
        <span>{escape(value)}</span>
        <p>{escape(note)}</p>
      </article>
    """


def _render_screen3_option_chips(
    options: list[Any],
    select_type: str,
    state_key: str,
    *,
    active_value: Any = None,
) -> str:
    if not options:
        return '<div class="meta">No selectable options are available.</div>'
    active_text = (_first_display_value(active_value) or "").strip().lower()
    chips = []
    for option in options:
        option_text = _first_display_value(option)
        if not option_text:
            continue
        active_class = " active" if option_text.strip().lower() == active_text else ""
        chips.append(
            f"""
            <span
              class="scope-chip{active_class}"
              data-dashboard-selectable="true"
              data-dashboard-select-type="{escape(select_type, quote=True)}"
              data-dashboard-select-key="{escape(state_key, quote=True)}"
              data-dashboard-select-id="{escape(option_text, quote=True)}"
              data-dashboard-filter-key="{escape(state_key, quote=True)}"
              data-dashboard-filter-value="{escape(option_text, quote=True)}"
              aria-selected="false"
            >{escape(option_text)}</span>
            """
        )
    return f'<div class="scope-chip-row">{"".join(chips)}</div>' if chips else '<div class="meta">No selectable options are available.</div>'


def _first_display_value(*values: Any) -> str | None:
    for value in values:
        if value is None:
            continue
        if isinstance(value, str) and not _has_display_value(value):
            continue
        if isinstance(value, (list, tuple, set)) and not value:
            continue
        text = _display_value(value).strip()
        if text and text != "Insufficient data for a reliable conclusion":
            return text
    return None


def _screen3_domain_key(value: Any) -> str | None:
    text = str(value or "").strip().upper()
    if not text:
        return None
    if "USER I/O" in text or " I/O" in text or text == "I/O":
        return "IO"
    if "COMMIT" in text or "LOG FILE SYNC" in text:
        return "COMMIT"
    for domain in SCREEN3_CONTROL_CENTER_DOMAINS:
        if domain in text:
            return domain
    return None


def _render_selection_controls(selection_controls: dict[str, Any]) -> str:
    if not selection_controls:
        return _render_empty_item("No selection controls are available.")
    controls = [
        _render_readonly_control("DB / DBID", selection_controls.get("db_dbid")),
        _render_readonly_control("Host / Instance", selection_controls.get("host_instance")),
        _render_readonly_control("Snapshot Window", selection_controls.get("snapshot_window")),
        _render_readonly_control("Latest Interval", selection_controls.get("latest_interval")),
        _render_readonly_control("Worst Interval", selection_controls.get("worst_interval")),
        _render_static_option_control(
            "Comparison Mode",
            selection_controls.get("comparison_modes") or [],
            selection_controls.get("active_comparison_mode"),
        ),
        _render_static_option_control(
            "Review Mode",
            selection_controls.get("review_modes") or [],
            selection_controls.get("active_review_mode"),
        ),
    ]
    return '<div class="selector-control-grid">' + "".join(controls) + "</div>"


def _render_readonly_control(label: str, value: Any) -> str:
    return f"""
      <label class="selector-control">
        <span>{escape(label)}</span>
        <input value="{escape(_display_value(value))}" readonly>
      </label>
    """


def _render_static_option_control(label: str, options: list[Any], active_value: Any) -> str:
    active_text = _display_value(active_value)
    option_chips = []
    active_normalized = active_text.strip().lower()
    for option in options:
        option_text = _display_value(option)
        active_class = (
            " active"
            if option_text.strip().lower() == active_normalized
            else ""
        )
        option_chips.append(
            f'<span class="scope-chip{active_class}">{escape(option_text)}</span>'
        )
    return f"""
      <label class="selector-control">
        <span>{escape(label)}</span>
        <input value="{escape(active_text)}" readonly>
        <div class="scope-chip-row static-option-row">{"".join(option_chips)}</div>
      </label>
    """


def _render_screen_4_page(
    screen_model: dict[str, Any],
    chart_payload: dict[str, Any],
    violin_metric_groups: list[dict[str, Any]],
    time_series_groups: list[dict[str, Any]],
    derived_scalar_metrics: dict[str, Any],
) -> str:
    normalized_decision = _to_dict(screen_model.get("normalized_decision"))
    header = _to_dict(screen_model.get("header"))
    current_selection_summary = _to_dict(screen_model.get("current_selection_summary"))
    historical_verdict = _to_dict(screen_model.get("historical_verdict"))
    visual_story = _to_dict(_to_dict(screen_model.get("visual_analysis")).get("story"))
    similarity_evidence = _to_dict(screen_model.get("similarity_evidence"))
    scalar_metrics_html = _render_scalar_metrics(derived_scalar_metrics)
    topology_scalar_html = _render_topology_scalar_fallback(
        _to_dict(chart_payload.get("violin_panel"))
    )
    time_series_section_html = _render_time_series_section(time_series_groups)
    visual_sections = {
        "performance": _render_performance_charts_section(chart_payload, visual_story),
        "time_series": time_series_section_html,
        "violin": _render_violin_panel(violin_metric_groups),
        "scalar": (
            f"""
      <section id="derived-scalar-metrics" class="card secondary">
        <div class="section-kicker">Supporting Visual Layer</div>
        <h2>Derived Scalar Metrics</h2>
        {scalar_metrics_html}
      </section>
    """
            if scalar_metrics_html
            else ""
        ),
    }
    ordered_visual_sections = "".join(
        visual_sections.get(section_key, "")
        for section_key in (visual_story.get("section_order") or ["performance", "time_series", "violin", "scalar"])
        if visual_sections.get(section_key, "")
    )
    engineering_view_html = _render_engineering_view(
        screen_model.get("engineering_view"),
        "Engineering View",
    )
    review_comparison_html = _render_review_comparison_screen(
        screen_model,
        normalized_decision=normalized_decision,
    )
    screen4_exploration_html = _render_screen4_historical_exploration(
        screen_model,
        chart_payload,
        violin_metric_groups,
        time_series_groups,
        derived_scalar_metrics,
    )
    screen4_review_preview_html = _render_screen4_historical_review_preview_panel(
        screen_model
    )
    return f"""
    <div class="grid">
      <!-- Screen 4 = historical review across scope + timeframe, with visuals. -->
      <section class="card secondary screen4-summary-card">
        <div class="section-kicker">Screen 4</div>
        <h2>Historical Review / Comparison</h2>
        <div class="meta">
          Historical evidence supports interpretation but does not override the selected-scope diagnostic truth.
        </div>
        <div class="subgrid">
          <section class="half evidence-pane screen4-compact-pane">
            <h3>Historical Scope</h3>
            {_render_info_grid(
                [
                    ("Scope", header.get("scope_label")),
                    ("Instance", header.get("instance_name")),
                    ("Host", header.get("host_name")),
                    (
                        "Window",
                        _format_window_summary(
                            header.get("snapshot_count"),
                            header.get("comparison_window"),
                        ),
                    ),
                ],
                extra_class="screen4-compact-info-grid",
            )}
          </section>
          <section class="half evidence-pane screen4-compact-pane">
            <h3>Current Selection Summary</h3>
            {_render_info_grid(
                [
                    ("Current Window", current_selection_summary.get("current_window")),
                    ("Comparison Mode", current_selection_summary.get("comparison_mode")),
                    (
                        "Latest vs Prior",
                        _screen4_compact_selection_text(
                            current_selection_summary.get("latest_vs_prior")
                        ),
                    ),
                ],
                extra_class="screen4-compact-info-grid",
            )}
          </section>
          <section class="evidence-pane screen4-verdict-pane">
            <h3>Historical Verdict</h3>
            <div class="meta">
              Historical / Supporting Context only; this does not override Screen 3 selected-scope diagnosis.
            </div>
            {_render_info_grid(
                [
                    ("Risk", historical_verdict.get("display_severity_label")),
                    ("Historical Stability", historical_verdict.get("historical_stability")),
                    ("Anomaly Burden", historical_verdict.get("anomaly_burden")),
                    ("Historical Posture", historical_verdict.get("historical_posture")),
                    (
                        "Similarity Context",
                        _screen4_similarity_context_label(similarity_evidence),
                    ),
                ],
                extra_class="screen4-verdict-grid",
            )}
          </section>
        </div>
      </section>
      {screen4_exploration_html}
      {screen4_review_preview_html}
      {ordered_visual_sections}
      {topology_scalar_html}
      {_render_similarity_evidence_section(similarity_evidence)}
      <section class="card secondary">
        {review_comparison_html}
      </section>
      {
          f'''
      <section class="card secondary">
        <h2>Technical Detail</h2>
        {engineering_view_html}
      </section>
      '''
          if engineering_view_html
          else ""
      }
    </div>
    """


def _screen4_compact_selection_text(value: Any) -> Any:
    if not _has_display_value(value):
        return value
    text = _display_value(value)
    text = text.replace(
        "The latest interval differs from the worst interval and should be interpreted in broader historical context.",
        "Latest differs from worst interval; interpret in broader historical context.",
    )
    return text


def _screen4_similarity_context_label(similarity_evidence: dict[str, Any]) -> str | None:
    if not similarity_evidence:
        return None
    if not similarity_evidence.get("enabled"):
        return "Similarity evidence unavailable"
    similar_count = len(similarity_evidence.get("similar_cases") or [])
    cluster = _to_dict(similarity_evidence.get("workload_cluster"))
    cluster_label = _display_cluster_summary_label(cluster.get("cluster_label"))
    if similar_count:
        return f"{similar_count} nearest-neighbor case(s); {cluster_label}"
    return cluster_label


def _render_screen4_historical_exploration(
    screen_model: dict[str, Any],
    chart_payload: dict[str, Any],
    violin_metric_groups: list[dict[str, Any]],
    time_series_groups: list[dict[str, Any]],
    derived_scalar_metrics: dict[str, Any],
) -> str:
    exploration = _build_screen4_historical_exploration_model(
        screen_model,
        chart_payload,
        violin_metric_groups,
        time_series_groups,
        derived_scalar_metrics,
    )
    return f"""
      <section class="card secondary screen4-historical-exploration">
        <div class="section-kicker">Screen 4 Historical Review Exploration</div>
        <h2>Screen 4 Historical Review Exploration</h2>
        <p class="meta">
          Read-only historical exploration. Exploratory only. No backend writes.
          Does not change historical truth. Does not recalculate trends.
          Does not reclassify anomalies. Does not change baseline.
          Does not change diagnostic truth. Does not change recommendation truth.
          Semantic/learning context is not historical evidence.
          Selection only highlights deterministic historical context.
          Cross-Screen Selection Propagation is browser-side only.
          URL hash/localStorage state is not authoritative truth.
          No approval controls. No runtime activation.
        </p>
        <div class="subgrid">
          <section class="evidence-pane selector-pane screen4-selected-historical-panel">
            <h3>Selected Historical Summary</h3>
            <p class="screen4-selected-historical-summary" data-dashboard-selected-summary data-dashboard-state-empty="true">
              Read-only historical exploration: no local selection. Selection is local and read-only. Historical output remains unchanged.
            </p>
            <div class="meta">
              Selection does not recalculate trends, reclassify anomalies, change baseline, change similarity results, change diagnostic truth, or change recommendation truth.
            </div>
          </section>
          {_render_screen4_selector_group(
              "Historical Domain Selector",
              "Domain selection is local and does not recalculate trends, anomalies, baseline, primary issue, or severity.",
              exploration["domain_controls"],
              "Historical domain controls are limited to fixed authoritative domains. Selection is local and read-only. Historical output remains unchanged.",
          )}
          {_render_screen4_selector_group(
              "Time Window Selector",
              "Window selection highlights existing historical context only. No trend recalculation.",
              exploration["time_windows"],
              "No additional historical windows available in this static export. Selection is local and read-only. Historical output remains unchanged.",
          )}
          {_render_screen4_selector_group(
              "Trend / Metric Selector",
              "Trend selection uses already rendered metrics only. No metric recalculation.",
              exploration["trend_metrics"],
              "No additional trend or metric groups available in this static export. Selection is local and read-only. Historical output remains unchanged.",
          )}
          {_render_screen4_selector_group(
              "Anomaly Selector",
              "Anomaly selection highlights deterministic anomaly context only. No reclassification.",
              exploration["anomaly_groups"],
              "No anomaly groups available in this static export. Selection is local and read-only. Historical output remains unchanged.",
          )}
          {_render_screen4_selector_group(
              "Violin / Distribution Selector",
              "Distribution selection highlights rendered distribution domains only. No distribution recalculation.",
              exploration["distribution_groups"],
              "No distribution selector available in this static export. Selection is local and read-only. Historical output remains unchanged.",
          )}
          {_render_screen4_selector_group(
              "Baseline / Similar Case Selector",
              "Baseline and similar-case selection uses deterministic output already present. No similarity recomputation.",
              exploration["baseline_similarity"],
              "No similar-case selector available in this static export. Selection is local and read-only. Historical output remains unchanged.",
          )}
        </div>
      </section>
    """


def _render_screen4_historical_review_preview_panel(
    screen_model: dict[str, Any],
) -> str:
    preview = _build_screen4_historical_review_preview_model(screen_model)
    controls = "".join(
        f"""
          <div class="screen4-historical-review-preview-card disabled-preview-only"
               aria-disabled="true"
               data-preview-only="true">
            <strong>{escape(item["label"])}</strong>
            <span>{escape(item["status"])}</span>
          </div>
        """
        for item in preview["controls"]
    )
    safety_labels = "".join(
        f"<span class=\"scope-chip\">{escape(label)}</span>"
        for label in preview["safety_labels"]
    )
    return f"""
      <section class="card secondary screen4-historical-review-preview-panel">
        <div class="section-kicker">Screen 4 Historical Review Preview</div>
        <h2>Screen 4 Historical Review / Learning Preview</h2>
        <p class="meta">
          Disabled / preview-only historical review controls for future governed
          workflow. These controls do not submit, route, write, or execute.
        </p>
        <div class="screen4-historical-review-preview-grid">
          {controls}
        </div>
        <div class="screen4-historical-review-preview-summary">
          {safety_labels}
        </div>
      </section>
    """


def _build_screen4_historical_review_preview_model(
    screen_model: dict[str, Any],
) -> dict[str, Any]:
    _ = screen_model
    control_labels = (
        "Approve Trend",
        "Dispute Trend",
        "Mark Trend Insufficient",
        "Approve Anomaly",
        "Mark Anomaly False Positive",
        "Mark Anomaly Insufficient",
        "Request Trend-Aware Scoring Review",
        "Request Anomaly Sensitivity Review",
        "Request Scoring Threshold Review",
        "Request Learning Candidate",
        "Add Historical Review Note",
    )
    safety_labels = (
        "Preview only",
        "Historical review disabled in this phase",
        "No trend truth mutation",
        "No anomaly truth mutation",
        "No scoring change",
        "No candidate created automatically",
        "No governed write path invoked",
        "No Phase 4I mutation",
        "Deterministic runtime remains authoritative",
    )
    return {
        "controls": [
            {"label": label, "status": "Disabled preview only"}
            for label in control_labels
        ],
        "safety_labels": list(safety_labels),
    }


def _build_screen4_historical_exploration_model(
    screen_model: dict[str, Any],
    chart_payload: dict[str, Any],
    violin_metric_groups: list[dict[str, Any]],
    time_series_groups: list[dict[str, Any]],
    derived_scalar_metrics: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    header = _to_dict(screen_model.get("header"))
    current_selection_summary = _to_dict(screen_model.get("current_selection_summary"))
    historical_verdict = _to_dict(screen_model.get("historical_verdict"))
    normalized_decision = _to_dict(screen_model.get("normalized_decision"))
    anomaly_review = _to_dict(screen_model.get("anomaly_review"))
    comparison_review = _to_dict(screen_model.get("comparison_review"))
    similarity_evidence = _to_dict(screen_model.get("similarity_evidence"))
    time_series_payload = _to_dict(chart_payload.get("time_series_charts"))
    domain_scores = _to_dict(normalized_decision.get("domain_scores"))
    primary_domain = _screen4_selector_domain(
        normalized_decision.get("primary_issue")
        or historical_verdict.get("primary_issue")
        or header.get("primary_issue")
    )

    domain_controls: list[dict[str, Any]] = []
    for domain in SCREEN4_HISTORICAL_EXPLORATION_DOMAINS:
        score = _screen2_domain_score(domain_scores, domain)
        _append_screen4_selector_item(
            domain_controls,
            label=domain,
            value=domain,
            select_type="historical-domain",
            state_key="selectedDomain",
            domain=domain,
            active=domain == primary_domain,
            display_value=(
                f"{score:.1f}" if score is not None else "Exploration domain"
            ),
            note="Historical domain selection only; no trend, anomaly, baseline, primary-issue, or severity change.",
        )

    time_windows: list[dict[str, Any]] = []
    window_summary = _format_window_summary(
        header.get("snapshot_count"),
        header.get("comparison_window"),
    )
    for label, raw_value, note in (
        ("Historical Window", window_summary, "Existing Screen 4 comparison window. No trend recalculation."),
        ("Current Window", current_selection_summary.get("current_window"), "Current selection context already rendered."),
        ("Latest Interval", comparison_review.get("latest_interval"), "Existing latest interval. No re-windowing."),
        ("Worst Interval", comparison_review.get("worst_interval"), "Existing worst interval. No baseline change."),
    ):
        if not _has_display_value(raw_value):
            continue
        _append_screen4_selector_item(
            time_windows,
            label=label,
            value=_screen4_state_id(raw_value),
            select_type="historical-window",
            state_key="selectedHistoricalWindow",
            display_value=raw_value,
            note=note,
        )
    snapshot_labels = [
        _display_value(label)
        for label in (time_series_payload.get("snapshot_labels") or [])
        if _has_display_value(label)
    ]
    if len(snapshot_labels) >= 2:
        _append_screen4_selector_item(
            time_windows,
            label="Snapshot Label Range",
            value=_screen4_state_id(f"{snapshot_labels[0]}-{snapshot_labels[-1]}"),
            select_type="historical-window",
            state_key="selectedHistoricalWindow",
            display_value=f"{snapshot_labels[0]} -> {snapshot_labels[-1]}",
            note="Rendered time-series label range. No trend recalculation.",
        )

    trend_metrics: list[dict[str, Any]] = []
    for group in time_series_groups:
        group_title = _display_value(group.get("group_title"))
        for chart in group.get("charts") or []:
            title = _display_value(chart.get("title") or chart.get("label"))
            if not title:
                continue
            chart_domain = _screen4_selector_domain(group.get("group_key") or title)
            _append_screen4_selector_item(
                trend_metrics,
                label=title,
                value=f"{_screen4_state_id(group.get('group_key'))}-{_screen4_state_id(chart.get('key') or title)}",
                select_type="trend-metric",
                state_key="selectedTrendMetric",
                domain=chart_domain,
                display_value=group_title or title,
                note="Rendered trend metric only. No metric recalculation.",
            )
    for label, value in _to_dict(derived_scalar_metrics).items():
        if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
            continue
        _append_screen4_selector_item(
            trend_metrics,
            label=_screen4_title_from_key(label),
            value=f"scalar-{_screen4_state_id(label)}",
            select_type="trend-metric",
            state_key="selectedTrendMetric",
            domain=_screen4_selector_domain(label),
            display_value=_format_scalar_metric(value),
            note="Derived scalar metric already rendered. No metric recalculation.",
        )

    anomaly_groups = _screen4_anomaly_selector_items(anomaly_review)
    distribution_groups = _screen4_distribution_selector_items(violin_metric_groups)
    baseline_similarity = _screen4_baseline_similarity_selector_items(
        current_selection_summary,
        comparison_review,
        similarity_evidence,
    )

    return {
        "domain_controls": _dedupe_screen4_selector_items(domain_controls),
        "time_windows": _dedupe_screen4_selector_items(time_windows),
        "trend_metrics": _dedupe_screen4_selector_items(trend_metrics),
        "anomaly_groups": _dedupe_screen4_selector_items(anomaly_groups),
        "distribution_groups": _dedupe_screen4_selector_items(distribution_groups),
        "baseline_similarity": _dedupe_screen4_selector_items(baseline_similarity),
    }


def _screen4_anomaly_selector_items(anomaly_review: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    anomalies = _to_dict(anomaly_review.get("anomalies"))
    anomaly_summary = _to_dict(anomaly_review.get("anomaly_summary"))
    count = _safe_float(anomalies.get("count") or anomaly_summary.get("count"))
    if count is not None and count > 0:
        _append_screen4_selector_item(
            items,
            label="Anomaly Review",
            value="anomaly-review",
            select_type="anomaly-group",
            state_key="selectedAnomalyGroup",
            display_value=f"{int(count)} anomaly group(s)",
            note="Deterministic anomaly summary only. No reclassification.",
        )
    windows = anomaly_summary.get("windows") or anomaly_summary.get("items") or []
    if isinstance(windows, dict):
        windows = list(windows.values())
    for index, window in enumerate(windows):
        window_dict = _to_dict(window) if isinstance(window, dict) else {}
        label = (
            window_dict.get("label")
            or window_dict.get("window")
            or window_dict.get("title")
            or window
        )
        if not _has_display_value(label):
            continue
        _append_screen4_selector_item(
            items,
            label=_display_value(label),
            value=f"anomaly-{index}-{_screen4_state_id(label)}",
            select_type="anomaly-group",
            state_key="selectedAnomalyGroup",
            domain=_screen4_selector_domain(label),
            display_value=window_dict.get("severity") or "Historical anomaly context",
            note="Existing anomaly window only. No anomaly reclassification.",
        )
    return _dedupe_screen4_selector_items(items)


def _screen4_distribution_selector_items(
    violin_metric_groups: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for group in violin_metric_groups:
        group_key = group.get("group_key")
        group_title = _display_value(group.get("group_title") or group_key)
        metrics = list(group.get("metrics") or [])
        if not group_title:
            continue
        _append_screen4_selector_item(
            items,
            label=group_title,
            value=_screen4_state_id(group_key or group_title),
            select_type="distribution",
            state_key="selectedDistribution",
            domain=_screen4_selector_domain(group_title),
            display_value=f"{len(metrics)} rendered distribution metric(s)",
            note=_display_value(group.get("group_note") or "Rendered distribution group. No distribution recalculation."),
        )
        for metric in metrics[:3]:
            title = _display_value(metric.get("title") or metric.get("payload_key"))
            if not title:
                continue
            _append_screen4_selector_item(
                items,
                label=title,
                value=f"{_screen4_state_id(group_key)}-{_screen4_state_id(metric.get('payload_key') or title)}",
                select_type="distribution",
                state_key="selectedDistribution",
                domain=_screen4_selector_domain(title),
                display_value=group_title,
                note="Rendered distribution metric only. No distribution recalculation.",
            )
    return _dedupe_screen4_selector_items(items)


def _screen4_baseline_similarity_selector_items(
    current_selection_summary: dict[str, Any],
    comparison_review: dict[str, Any],
    similarity_evidence: dict[str, Any],
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    baseline_pairs = (
        ("Comparison Mode", current_selection_summary.get("comparison_mode")),
        ("Latest vs Prior", current_selection_summary.get("latest_vs_prior")),
        ("Latest vs Trend", comparison_review.get("latest_vs_trend")),
        ("Drift Summary", comparison_review.get("drift_summary")),
    )
    for label, value in baseline_pairs:
        if not _has_display_value(value):
            continue
        _append_screen4_selector_item(
            items,
            label=label,
            value=f"baseline-{_screen4_state_id(label)}",
            select_type="comparison-baseline",
            state_key="selectedComparisonBaseline",
            display_value=value,
            note="Existing comparison baseline context only. No baseline change.",
        )
    if similarity_evidence.get("enabled"):
        for index, case in enumerate(similarity_evidence.get("similar_cases") or []):
            case_dict = _to_dict(case)
            case_id = (
                case_dict.get("awr_id")
                or case_dict.get("id")
                or case_dict.get("db_name")
                or f"case-{index + 1}"
            )
            _append_screen4_selector_item(
                items,
                label=f"Similar Case {_display_value(case_id)}",
                value=f"similar-{_screen4_state_id(case_id)}",
                select_type="similar-case",
                state_key="selectedSimilarCase",
                domain=_screen4_selector_domain(case_dict.get("primary_signal_domain")),
                display_value=case_dict.get("db_name") or case_dict.get("workload_class") or "Nearest-neighbor case",
                note="Deterministic similar-case row already present. No similarity recomputation.",
            )
    return _dedupe_screen4_selector_items(items)


def _append_screen4_selector_item(
    items: list[dict[str, Any]],
    *,
    label: Any,
    value: Any,
    select_type: str,
    state_key: str,
    display_value: Any = None,
    note: Any = None,
    domain: Any = None,
    active: bool = False,
) -> None:
    if not _has_display_value(label) or not _has_display_value(value):
        return
    domain_text = _screen4_selector_domain(domain)
    items.append(
        {
            "label": _display_value(label),
            "value": _display_value(value),
            "select_type": select_type,
            "state_key": state_key,
            "display_value": _display_value(display_value) if _has_display_value(display_value) else "",
            "note": _display_value(note) if _has_display_value(note) else "",
            "domain": domain_text,
            "active": active,
        }
    )


def _render_screen4_selector_group(
    title: str,
    description: str,
    items: list[dict[str, Any]],
    empty_message: str,
) -> str:
    if not items:
        return f"""
          <section class="evidence-pane selector-pane">
            <h3>{escape(title)}</h3>
            <p class="meta">{escape(description)}</p>
            <div class="item">
              <p>{escape(empty_message)}</p>
            </div>
          </section>
        """
    cards = "".join(_render_screen4_selector_card(item) for item in items)
    return f"""
          <section class="evidence-pane selector-pane">
            <h3>{escape(title)}</h3>
            <p class="meta">{escape(description)}</p>
            <div class="screen4-selector-grid">{cards}</div>
          </section>
    """


def _render_screen4_selector_card(item: dict[str, Any]) -> str:
    select_type = _display_value(item.get("select_type"))
    state_key = _display_value(item.get("state_key"))
    value = _display_value(item.get("value"))
    domain = _display_value(item.get("domain")) if _has_display_value(item.get("domain")) else ""
    active_class = " active" if item.get("active") else ""
    domain_attribute = (
        f' data-dashboard-select-domain="{escape(domain, quote=True)}"'
        if domain
        else ""
    )
    return f"""
              <article
                class="screen4-selector-card{active_class}"
                data-dashboard-selectable="true"
                data-dashboard-select-type="{escape(select_type, quote=True)}"
                data-dashboard-select-key="{escape(state_key, quote=True)}"
                data-dashboard-select-id="{escape(value, quote=True)}"
                data-dashboard-filter-key="{escape(state_key, quote=True)}"
                data-dashboard-filter-value="{escape(value, quote=True)}"{domain_attribute}
                data-selected="false"
                aria-selected="false"
                tabindex="0"
              >
                <strong>{escape(select_type.replace("-", " ").title())}</strong>
                <span>{escape(_display_value(item.get("label")))}</span>
                {
                    f'<p>{escape(_display_value(item.get("display_value")))}</p>'
                    if _has_display_value(item.get("display_value"))
                    else ""
                }
                {
                    f'<p>{escape(_display_value(item.get("note")))}</p>'
                    if _has_display_value(item.get("note"))
                    else ""
                }
              </article>
    """


def _screen4_selector_domain(value: Any) -> str | None:
    text = str(value or "").strip().upper()
    if not text:
        return None
    if "USER I/O" in text or "USER IO" in text:
        return "IO"
    if "LOG FILE" in text or "COMMIT" in text:
        return "COMMIT"
    if "CLUSTER" in text or "GC " in text or "RAC" in text:
        return "RAC"
    if "DATA GUARD" in text or "TRANSPORT" in text or "APPLY LAG" in text or "ADG" in text:
        return "ADG"
    if "PGA" in text or "MEMORY" in text or "TEMP" in text:
        return "MEMORY"
    if "CPU" in text:
        return "CPU"
    if "IO" in text or "I/O" in text:
        return "IO"
    for domain in SCREEN4_HISTORICAL_EXPLORATION_DOMAINS:
        if domain in text:
            return domain
    return None


def _screen4_state_id(value: Any) -> str:
    text = re.sub(r"[^a-zA-Z0-9]+", "-", _display_value(value).strip().lower())
    return text.strip("-")[:80] or "selection"


def _screen4_title_from_key(value: Any) -> str:
    text = re.sub(r"[_\-]+", " ", _display_value(value)).strip()
    return text.title() if text else "Historical Metric"


def _dedupe_screen4_selector_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[tuple[str, str]] = set()
    deduped: list[dict[str, Any]] = []
    for item in items:
        key = (_display_value(item.get("state_key")), _display_value(item.get("value")))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped


def _render_screen5_recommendation_action_exploration(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
) -> str:
    exploration = _build_screen5_recommendation_action_exploration_model(
        screen_model,
        report_data,
    )
    return f"""
      <section class="card secondary screen5-recommendation-action-exploration">
        <div class="section-kicker">Screen 5 Recommendation Action & Outcome Exploration</div>
        <h2>Screen 5 Recommendation Action & Outcome Exploration</h2>
        <p class="meta">
          Read-only recommendation/action exploration. Exploratory only. No backend writes.
          Does not change recommendation truth. Does not change recommendation priority.
          Does not change recommendation rationale. Does not change supporting evidence.
          Does not change diagnostic truth. Learning candidates are not recommendation evidence.
          Semantic context is not recommendation evidence.
          Selection only highlights existing recommendation/action context.
          Cross-Screen Selection Propagation is browser-side only.
          URL hash/localStorage state is not authoritative truth.
          No approval controls. No runtime activation.
        </p>
        <div class="subgrid">
          <section class="evidence-pane selector-pane screen5-selected-recommendation-panel">
            <h3>Selected Recommendation / Action Summary</h3>
            <p class="screen5-selected-recommendation-summary" data-dashboard-selected-summary data-dashboard-state-empty="true">
              Read-only recommendation/action exploration: no local selection. Selection is local and read-only. Recommendation output remains unchanged.
            </p>
            <div class="meta">
              Selection does not change recommendation truth, recommendation priority, recommendation rationale, supporting evidence, action status, outcome status, feedback status, diagnostic truth, or historical truth.
            </div>
          </section>
          {_render_screen5_selector_group(
              "Recommendation Selector",
              "Recommendation selection highlights existing deterministic recommendation objects only. It does not change recommendation truth, priority, rationale, or evidence.",
              exploration["recommendations"],
              "No deterministic recommendation controls available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Recommendation Domain Selector",
              "Domain selection is local and does not filter or change recommendation truth.",
              exploration["domains"],
              "Recommendation domain controls are limited to fixed authoritative domains. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Recommendation Category Selector",
              "Category selection uses recommendation category metadata when present. No recommendation ranking or rationale changes.",
              exploration["categories"],
              "No additional recommendation categories available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Supporting Evidence Link Selector",
              "Evidence selection highlights deterministic evidence context already shown. It does not alter evidence.",
              exploration["evidence"],
              "No supporting evidence links available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Action Context Selector",
              "Action context selection is read-only and performs no action tracking writes or status mutation.",
              exploration["actions"],
              "No action context available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Outcome Context Selector",
              "Outcome context selection is read-only and performs no outcome tracking writes or status mutation.",
              exploration["outcomes"],
              "No outcome context available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Feedback Context Selector",
              "Feedback context selection is read-only and performs no feedback writes or status mutation.",
              exploration["feedback"],
              "No feedback context available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
          {_render_screen5_selector_group(
              "Related Learning Context Selector",
              "Related learning context is review/proposal context only, not recommendation evidence, not automatically applied, runtime_influence=false.",
              exploration["learning"],
              "No related learning candidate review context available in this static export. Selection is local and read-only. Recommendation output remains unchanged.",
          )}
        </div>
      </section>
    """


def _build_screen5_recommendation_action_exploration_model(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    header = _to_dict(screen_model.get("header"))
    normalized_decision = _to_dict(screen_model.get("normalized_decision"))
    recommendation_list = list(screen_model.get("recommendation_list") or [])
    recommendation_groups = list(screen_model.get("recommendation_groups") or [])
    evidence_tie_back = _to_dict(screen_model.get("recommendation_evidence_tie_back"))
    validation_focus_areas = list(screen_model.get("validation_focus_areas") or [])
    posture_guidance = list(screen_model.get("posture_guidance") or [])
    primary_domain = _screen5_selector_domain(
        header.get("primary_issue")
        or normalized_decision.get("primary_issue")
        or header.get("domain")
    )
    domain_scores = _to_dict(normalized_decision.get("domain_scores"))

    recommendations = _screen5_recommendation_selector_items(
        recommendation_groups or recommendation_list
    )
    domains: list[dict[str, Any]] = []
    for domain in SCREEN5_RECOMMENDATION_ACTION_DOMAINS:
        score = _screen2_domain_score(domain_scores, domain)
        _append_screen5_selector_item(
            domains,
            label=domain,
            value=domain,
            select_type="recommendation-domain",
            state_key="selectedDomain",
            domain=domain,
            active=domain == primary_domain,
            display_value=f"{score:.1f}" if score is not None else "Exploration domain",
            note="Recommendation domain selection only. No recommendation truth change.",
        )

    categories = _screen5_recommendation_category_items(
        recommendation_groups,
        recommendation_list,
    )
    evidence = _screen5_recommendation_evidence_items(
        evidence_tie_back,
        validation_focus_areas,
    )
    actions = _screen5_action_context_items(screen_model, report_data, posture_guidance)
    outcomes = _screen5_context_items(
        _screen5_first_context_collection(
            screen_model,
            report_data,
            (
                "outcome_context",
                "outcome_contexts",
                "outcomes",
                "outcome_history",
                "action_outcomes",
            ),
        ),
        select_type="outcome-context",
        state_key="selectedOutcomeContext",
        default_label="Outcome Context",
        note="Outcome context only. No outcome tracking writes or status mutation.",
    )
    feedback = _screen5_context_items(
        _screen5_first_context_collection(
            screen_model,
            report_data,
            (
                "feedback_context",
                "feedback_contexts",
                "feedback",
                "feedback_history",
                "operator_feedback",
            ),
        ),
        select_type="feedback-context",
        state_key="selectedFeedbackContext",
        default_label="Feedback Context",
        note="Feedback context only. No feedback writes or status mutation.",
    )
    learning = _screen5_learning_context_items(
        _screen5_first_context_collection(
            screen_model,
            {},
            (
                "related_learning_candidates",
                "learning_candidate_context",
                "learning_candidates",
            ),
        )
    )

    return {
        "recommendations": _dedupe_screen5_selector_items(recommendations),
        "domains": _dedupe_screen5_selector_items(domains),
        "categories": _dedupe_screen5_selector_items(categories),
        "evidence": _dedupe_screen5_selector_items(evidence),
        "actions": _dedupe_screen5_selector_items(actions),
        "outcomes": _dedupe_screen5_selector_items(outcomes),
        "feedback": _dedupe_screen5_selector_items(feedback),
        "learning": _dedupe_screen5_selector_items(learning),
    }


def _screen5_recommendation_selector_items(recommendations: list[Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for index, recommendation in enumerate(_screen5_flatten_recommendations(recommendations)):
        rec = _to_dict(recommendation)
        label = (
            rec.get("issue")
            or rec.get("recommendation")
            or rec.get("action")
            or rec.get("title")
            or f"Recommendation {index + 1}"
        )
        category = rec.get("category_label") or rec.get("category") or rec.get("type")
        priority = rec.get("priority") or rec.get("severity")
        _append_screen5_selector_item(
            items,
            label=label,
            value=f"recommendation-{index + 1}-{_screen5_state_id(label)}",
            select_type="recommendation",
            state_key="selectedRecommendation",
            domain=_screen5_selector_domain(rec.get("domain") or rec.get("issue") or rec.get("issue_type") or label),
            display_value=priority or category or "Deterministic recommendation",
            note="Existing recommendation object only. No priority, rank, rationale, or evidence change.",
        )
    return items


def _screen5_recommendation_category_items(
    recommendation_groups: list[Any],
    recommendation_list: list[Any],
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for index, group in enumerate(recommendation_groups):
        group_dict = _to_dict(group)
        title = group_dict.get("title") or group_dict.get("category")
        group_items = list(group_dict.get("items") or [])
        if not _has_display_value(title):
            continue
        _append_screen5_selector_item(
            items,
            label=title,
            value=f"category-{index + 1}-{_screen5_state_id(title)}",
            select_type="recommendation-category",
            state_key="selectedRecommendationCategory",
            domain=_screen5_selector_domain(title),
            display_value=f"{len(group_items)} recommendation item(s)",
            note="Existing recommendation category only. No ranking or rationale change.",
        )
    seen_categories = {
        _screen5_state_id(item.get("label"))
        for item in items
    }
    for index, recommendation in enumerate(recommendation_list):
        rec = _to_dict(recommendation)
        category = rec.get("category_label") or rec.get("category") or rec.get("type")
        if not _has_display_value(category):
            continue
        category_key = _screen5_state_id(category)
        if category_key in seen_categories:
            continue
        seen_categories.add(category_key)
        _append_screen5_selector_item(
            items,
            label=category,
            value=f"category-{index + 1}-{category_key}",
            select_type="recommendation-category",
            state_key="selectedRecommendationCategory",
            domain=_screen5_selector_domain(category),
            display_value="Recommendation category",
            note="Existing recommendation category only. No ranking or rationale change.",
        )
    return items


def _screen5_recommendation_evidence_items(
    evidence_tie_back: dict[str, Any],
    validation_focus_areas: list[Any],
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    primary = _to_dict(evidence_tie_back.get("primary_evidence"))
    if _has_meaningful_evidence(primary):
        label = primary.get("domain") or primary.get("issue_type") or "Primary Evidence"
        _append_screen5_selector_item(
            items,
            label=label,
            value=f"primary-{_screen5_state_id(label)}",
            select_type="recommendation-evidence",
            state_key="selectedRecommendationEvidence",
            domain=_screen5_selector_domain(label),
            display_value=primary.get("summary") or "Primary supporting evidence",
            note="Deterministic supporting evidence only. No evidence value change.",
        )
    for index, evidence in enumerate(evidence_tie_back.get("secondary_evidence") or []):
        evidence_dict = _to_dict(evidence)
        if not _has_meaningful_evidence(evidence_dict):
            continue
        label = evidence_dict.get("domain") or evidence_dict.get("issue_type") or f"Secondary Evidence {index + 1}"
        _append_screen5_selector_item(
            items,
            label=label,
            value=f"secondary-{index + 1}-{_screen5_state_id(label)}",
            select_type="recommendation-evidence",
            state_key="selectedRecommendationEvidence",
            domain=_screen5_selector_domain(label),
            display_value=evidence_dict.get("summary") or "Secondary supporting evidence",
            note="Deterministic supporting evidence only. No evidence value change.",
        )
    for index, focus_area in enumerate(validation_focus_areas):
        focus = _to_dict(focus_area)
        title = focus.get("title") or f"Evidence Checklist {index + 1}"
        if not _has_display_value(title):
            continue
        item_count = len(focus.get("items") or [])
        _append_screen5_selector_item(
            items,
            label=title,
            value=f"focus-{index + 1}-{_screen5_state_id(title)}",
            select_type="recommendation-evidence",
            state_key="selectedRecommendationEvidence",
            domain=_screen5_selector_domain(title),
            display_value=f"{item_count} checklist item(s)" if item_count else "Evidence checklist",
            note="Existing evidence checklist group only. No evidence value change.",
        )
    return items


def _screen5_action_context_items(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
    posture_guidance: list[Any],
) -> list[dict[str, Any]]:
    items = _screen5_context_items(
        _screen5_first_context_collection(
            screen_model,
            report_data,
            (
                "action_context",
                "action_contexts",
                "action_history",
                "actions",
                "action_records",
            ),
        ),
        select_type="action-context",
        state_key="selectedActionContext",
        default_label="Action Context",
        note="Action context only. No action tracking writes or status mutation.",
    )
    for index, guidance in enumerate(posture_guidance):
        if not _has_display_value(guidance):
            continue
        _append_screen5_selector_item(
            items,
            label=f"Validation Action {index + 1}",
            value=f"guidance-{index + 1}",
            select_type="action-context",
            state_key="selectedActionContext",
            display_value=guidance,
            note="Posture guidance already rendered in the validation plan. No action status mutation.",
        )
    return items


def _screen5_context_items(
    raw_items: Any,
    *,
    select_type: str,
    state_key: str,
    default_label: str,
    note: str,
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for index, raw_item in enumerate(_screen5_list(raw_items)):
        item = _to_dict(raw_item) if isinstance(raw_item, dict) else {}
        label = (
            item.get("title")
            or item.get("label")
            or item.get("name")
            or item.get("status")
            or item.get("id")
            or item.get("action_id")
            or item.get("outcome_id")
            or item.get("feedback_id")
            or raw_item
            or f"{default_label} {index + 1}"
        )
        if not _has_display_value(label):
            continue
        display_value = (
            item.get("summary")
            or item.get("description")
            or item.get("value")
            or item.get("status")
            or item.get("result")
            or item.get("feedback_text")
            or raw_item
        )
        _append_screen5_selector_item(
            items,
            label=label,
            value=f"{_screen5_state_id(select_type)}-{index + 1}-{_screen5_state_id(label)}",
            select_type=select_type,
            state_key=state_key,
            domain=_screen5_selector_domain(label),
            display_value=display_value,
            note=note,
        )
    return items


def _screen5_learning_context_items(raw_items: Any) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for index, raw_item in enumerate(_screen5_list(raw_items)):
        item = _to_dict(raw_item) if isinstance(raw_item, dict) else {}
        label = (
            item.get("candidate_id")
            or item.get("id")
            or item.get("title")
            or item.get("candidate_type")
            or raw_item
            or f"Learning Candidate {index + 1}"
        )
        if not _has_display_value(label):
            continue
        _append_screen5_selector_item(
            items,
            label=label,
            value=f"learning-{index + 1}-{_screen5_state_id(label)}",
            select_type="learning-candidate",
            state_key="selectedLearningCandidate",
            domain=_screen5_selector_domain(item.get("domain") or item.get("candidate_type") or label),
            display_value=item.get("summary") or item.get("description") or "Review/proposal context only; runtime_influence=false.",
            note="Review/proposal context only. Not recommendation evidence. Not automatically applied. runtime_influence=false.",
        )
    return items


def _screen5_first_context_collection(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
    keys: tuple[str, ...],
) -> Any:
    for source in (screen_model, report_data):
        for key in keys:
            value = source.get(key)
            if value:
                return value
    return []


def _screen5_flatten_recommendations(recommendations: list[Any]) -> list[Any]:
    flattened: list[Any] = []
    for item in recommendations:
        item_dict = _to_dict(item) if isinstance(item, dict) else {}
        if item_dict.get("items"):
            flattened.extend(item_dict.get("items") or [])
        else:
            flattened.append(item)
    return flattened


def _screen5_list(value: Any) -> list[Any]:
    if not value:
        return []
    if isinstance(value, list):
        return value
    if isinstance(value, tuple):
        return list(value)
    if isinstance(value, dict):
        if isinstance(value.get("items"), list):
            return list(value.get("items") or [])
        if isinstance(value.get("records"), list):
            return list(value.get("records") or [])
        if isinstance(value.get("contexts"), list):
            return list(value.get("contexts") or [])
        return [value]
    return [value]


def _append_screen5_selector_item(
    items: list[dict[str, Any]],
    *,
    label: Any,
    value: Any,
    select_type: str,
    state_key: str,
    display_value: Any = None,
    note: Any = None,
    domain: Any = None,
    active: bool = False,
) -> None:
    if not _has_display_value(label) or not _has_display_value(value):
        return
    domain_text = _screen5_selector_domain(domain)
    items.append(
        {
            "label": _display_value(label),
            "value": _display_value(value),
            "select_type": select_type,
            "state_key": state_key,
            "display_value": _display_value(display_value) if _has_display_value(display_value) else "",
            "note": _display_value(note) if _has_display_value(note) else "",
            "domain": domain_text,
            "active": active,
        }
    )


def _render_screen5_selector_group(
    title: str,
    description: str,
    items: list[dict[str, Any]],
    empty_message: str,
) -> str:
    if not items:
        return f"""
          <section class="evidence-pane selector-pane">
            <h3>{escape(title)}</h3>
            <p class="meta">{escape(description)}</p>
            <div class="item">
              <p>{escape(empty_message)}</p>
            </div>
          </section>
        """
    cards = "".join(_render_screen5_selector_card(item) for item in items)
    return f"""
          <section class="evidence-pane selector-pane">
            <h3>{escape(title)}</h3>
            <p class="meta">{escape(description)}</p>
            <div class="screen5-selector-grid">{cards}</div>
          </section>
    """


def _render_screen5_selector_card(item: dict[str, Any]) -> str:
    select_type = _display_value(item.get("select_type"))
    state_key = _display_value(item.get("state_key"))
    value = _display_value(item.get("value"))
    domain = _display_value(item.get("domain")) if _has_display_value(item.get("domain")) else ""
    active_class = " active" if item.get("active") else ""
    domain_attribute = (
        f' data-dashboard-select-domain="{escape(domain, quote=True)}"'
        if domain
        else ""
    )
    return f"""
              <article
                class="screen5-selector-card{active_class}"
                data-dashboard-selectable="true"
                data-dashboard-select-type="{escape(select_type, quote=True)}"
                data-dashboard-select-key="{escape(state_key, quote=True)}"
                data-dashboard-select-id="{escape(value, quote=True)}"
                data-dashboard-filter-key="{escape(state_key, quote=True)}"
                data-dashboard-filter-value="{escape(value, quote=True)}"{domain_attribute}
                data-selected="false"
                aria-selected="false"
                tabindex="0"
              >
                <strong>{escape(select_type.replace("-", " ").title())}</strong>
                <span>{escape(_display_value(item.get("label")))}</span>
                {
                    f'<p>{escape(_display_value(item.get("display_value")))}</p>'
                    if _has_display_value(item.get("display_value"))
                    else ""
                }
                {
                    f'<p>{escape(_display_value(item.get("note")))}</p>'
                    if _has_display_value(item.get("note"))
                    else ""
                }
              </article>
    """


def _screen5_selector_domain(value: Any) -> str | None:
    text = str(value or "").strip().upper()
    if not text:
        return None
    if "USER I/O" in text or "USER IO" in text:
        return "IO"
    if "LOG FILE" in text or "COMMIT" in text or "TRANSACTION" in text:
        return "COMMIT"
    if "CLUSTER" in text or "GC " in text or "RAC" in text:
        return "RAC"
    if "DATA GUARD" in text or "TRANSPORT" in text or "APPLY LAG" in text or "ADG" in text:
        return "ADG"
    if "PGA" in text or "MEMORY" in text or "TEMP" in text:
        return "MEMORY"
    if "CPU" in text or "SQL" in text:
        return "CPU"
    if "IO" in text or "I/O" in text:
        return "IO"
    for domain in SCREEN5_RECOMMENDATION_ACTION_DOMAINS:
        if domain in text:
            return domain
    return None


def _screen5_state_id(value: Any) -> str:
    text = re.sub(r"[^a-zA-Z0-9]+", "-", _display_value(value).strip().lower())
    return text.strip("-")[:80] or "selection"


def _dedupe_screen5_selector_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[tuple[str, str]] = set()
    deduped: list[dict[str, Any]] = []
    for item in items:
        key = (_display_value(item.get("state_key")), _display_value(item.get("value")))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped


