def _build_screen5_outcome_preview(
    screen_model: dict[str, Any],
    report_data: dict[str, Any],
) -> dict[str, str]:
    recommendation = _screen5_first_recommendation_for_action_preview(screen_model)
    action_preview = _build_screen5_action_tracking_preview(screen_model, report_data)
    recommendation_id = (
        recommendation.get("recommendation_id")
        or recommendation.get("id")
        or recommendation.get("recommendation_key")
        or action_preview.get("recommendation_id")
    )
    if not _has_display_value(recommendation_id) or _display_value(recommendation_id) == "no recommendation selected":
        recommendation_id = "no recommendation selected"
    linked_action_id = (
        recommendation.get("action_id")
        or recommendation.get("id")
        or (
            f"preview-action-{_screen5_state_id(action_preview.get('action_title'))}"
            if _has_display_value(action_preview.get("action_title"))
            else None
        )
    )
    return {
        "selected_recommendation_action_state": "no selected recommendation/action exists",
        "recommendation_id": _display_value(recommendation_id),
        "linked_action_id": (
            _display_value(linked_action_id)
            if _has_display_value(linked_action_id)
            else "no linked action selected"
        ),
        "outcome_status": "pending",
        "outcome_effectiveness": "unknown",
        "issue_recurred": "unknown preview",
        "followup_awr": "not linked",
        "followup_run": "not linked",
        "implementation_date": action_preview.get("implementation_date") or "not set",
        "outcome_notes": "not captured",
        "actor_required": "actor required before future outcome capture",
        "audit_required": "audit required before future outcome capture",
        "governed_write_path_required": "governed write path required before future write",
    }


def _render_parser_review_section(payload: dict[str, Any]) -> str:
    if not payload.get("available"):
        body = _render_empty_item("Data unavailable for this run.")
    else:
        summary = _to_dict(payload.get("summary"))
        body = f"""
        <div class="parser-review-grid">
          {_render_memory_count_card("Total unknown signals", summary.get("TOTAL"), "neutral")}
          {_render_memory_count_card("NEW", summary.get("NEW"), _parser_review_status_class("NEW"))}
          {_render_memory_count_card("REVIEWED", summary.get("REVIEWED"), _parser_review_status_class("REVIEWED"))}
          {_render_memory_count_card("CLASSIFIED", summary.get("CLASSIFIED"), _parser_review_status_class("CLASSIFIED"))}
          {_render_memory_count_card("IGNORED", summary.get("IGNORED"), _parser_review_status_class("IGNORED"))}
        </div>
        {_render_unknown_signal_pattern_summary(payload.get("pattern_summary") or [])}
        {_render_parser_review_list(payload.get("recent_unknowns") or [])}
        """
    return f"""
      <section class="card secondary parser-review-card">
        <div class="section-kicker">Phase 6 Parser Review</div>
        <h2>Parser Review & Unknown Signals</h2>
        <p class="meta">
          Parser review records are read-only in this phase. Classification and approval workflows are tracked through Phase 6 memory, with interactive controls planned for a future release.
        </p>
        {body}
      </section>
    """


def _render_unknown_signal_pattern_summary(patterns: list[dict[str, Any]]) -> str:
    if not patterns:
        return _render_empty_item("No grouped parser patterns are available.")
    rendered_patterns = []
    for pattern in patterns[:3]:
        status_parts = []
        for status in ("NEW", "REVIEWED", "CLASSIFIED", "IGNORED"):
            count = int(pattern.get("status_breakdown", {}).get(status) or 0)
            if count:
                status_parts.append(
                    f'<span class="mini-pill {escape(_parser_review_status_class(status))}">{escape(status)} {count}</span>'
                )
        class_parts = [
            f"{escape(classification)} {escape(str(count))}"
            for classification, count in sorted(
                _to_dict(pattern.get("classification_breakdown")).items()
            )
            if _has_display_value(classification)
        ]
        rendered_patterns.append(
            f"""
            <article class="unknown-pattern-row">
              <div>
                <strong>{escape(_memory_cell_text(pattern.get("section_name")))}</strong>
                <span>{escape(_memory_cell_text(pattern.get("unknown_type")))}</span>
              </div>
              <div>{escape(_truncate_memory_text(pattern.get("detection_reason"), 120))}</div>
              <div><span class="mini-pill neutral">{escape(str(pattern.get("count") or 0))} records</span></div>
              <div class="mini-pill-group">{''.join(status_parts) or escape("—")}</div>
              <div>{", ".join(class_parts) if class_parts else "—"}</div>
              <div>{escape(_format_unknown_signal_example_ids(pattern.get("example_ids") or []))}</div>
            </article>
            """
        )
    overflow = (
        '<p class="meta">Additional parser pattern groups are available in AWR_UNKNOWN_SIGNAL_HISTORY.</p>'
        if len(patterns) > 3
        else ""
    )
    return f"""
        <div class="parser-pattern-summary">
          <h3>Grouped Parser Pattern Summary</h3>
          <p class="meta">Summary groups repeated parser patterns for readability. Individual records remain separately tracked and reviewable.</p>
          <div class="unknown-pattern-list">
            <div class="unknown-pattern-row unknown-pattern-header">
              <div>Pattern / Section</div>
              <div>Reason</div>
              <div>Count</div>
              <div>Status Breakdown</div>
              <div>Class Breakdown</div>
              <div>Example IDs</div>
            </div>
            {"".join(rendered_patterns)}
          </div>
          {overflow}
        </div>
    """


def _render_parser_review_list(rows: list[dict[str, Any]]) -> str:
    if not rows:
        return _render_empty_item("No recent unknown signal records are available.")
    rendered_rows = []
    for row in rows:
        status = _memory_cell_text(row.get("review_status"))
        classification = _memory_cell_text(row.get("review_classification"))
        review_action = _parser_review_action_text(status)
        rendered_rows.append(
            f"""
            <article class="parser-review-row">
              <div>
                <strong>#{escape(_memory_cell_text(row.get("unknown_signal_id")))}</strong>
                <span>{escape(_memory_cell_text(row.get("section_name")))}</span>
              </div>
              <div>{escape(_memory_cell_text(row.get("unknown_type")))}</div>
              <div>{escape(_truncate_memory_text(row.get("detection_reason"), 120))}</div>
              <div><span class="mini-pill {escape(_parser_review_status_class(status))}">{escape(status)}</span></div>
              <div>{escape(classification)}</div>
              <div>{escape(_memory_cell_text(row.get("reviewed_by")))}</div>
              <div>{escape(_memory_cell_text(row.get("reviewed_at")))}</div>
              <div>{escape(review_action)}</div>
            </article>
            """
        )
    return f"""
        <div class="parser-review-list">
          <h3>Individual Unknown Signal Records</h3>
          <p class="meta">Grouped patterns summarize repeated parser findings. Individual records are shown because each record remains separately reviewable.</p>
          <div class="parser-review-row parser-review-header">
            <div>ID / Section</div>
            <div>Type</div>
            <div>Detection Reason</div>
            <div>Status</div>
            <div>Class</div>
            <div>Reviewed By</div>
            <div>Reviewed At</div>
            <div>Review Action</div>
          </div>
          {"".join(rendered_rows)}
        </div>
    """


def _render_parser_governance_review_section(payload: dict[str, Any]) -> str:
    if not payload.get("available"):
        body = _render_empty_item("No governance review records available.")
    else:
        items = list(payload.get("items") or [])
        if not items:
            body = _render_empty_item("No governance review records available.")
        else:
            body = _render_parser_governance_items(items)
    return f"""
      <section class="card secondary parser-governance-card">
        <div class="section-kicker">READ-ONLY Governance Visibility</div>
        <h2>Parser Governance Review</h2>
        <p class="meta">
          Governance review visibility is read-only in this phase. Approval workflows, parser governance actions, and controlled knowledge updates remain outside runtime analysis.
        </p>
        {body}
      </section>
    """


def _render_parser_governance_items(items: list[dict[str, Any]]) -> str:
    rendered_items = []
    for item in items:
        review_status = _governance_display_value(item.get("review_status"), "Unknown")
        approval_status = _governance_display_value(item.get("approval_status"), "Not Available")
        rendered_items.append(
            f"""
            <article class="parser-governance-row">
              <div>{escape(_governance_display_value(item.get("parser_stage"), "Unknown"))}</div>
              <div>{escape(_governance_display_value(item.get("classification_hint"), "Unknown"))}</div>
              <div><span class="mini-pill {escape(_parser_review_status_class(review_status))}">{escape(review_status)}</span></div>
              <div><span class="mini-pill {escape(_governance_approval_status_class(approval_status))}">{escape(approval_status)}</span></div>
              <div>{escape(_governance_display_value(item.get("source_file"), "Not Available"))}</div>
              <div>{escape(_governance_display_value(item.get("first_seen_timestamp"), "Not Available"))}</div>
              <div>{escape(_governance_display_value(item.get("last_seen_timestamp"), "Not Available"))}</div>
            </article>
            """
        )
    return f"""
        <div class="parser-governance-list">
          <div class="parser-governance-row parser-governance-header">
            <div>parser_stage</div>
            <div>classification_hint</div>
            <div>review_status</div>
            <div>approval_status</div>
            <div>source_file</div>
            <div>first_seen_timestamp</div>
            <div>last_seen_timestamp</div>
          </div>
          {"".join(rendered_items)}
        </div>
    """


def _render_governance_visibility_section(payload: dict[str, Any]) -> str:
    if not payload.get("available"):
        body = f"""
        {_render_empty_item("No governance review records available.")}
        {_render_empty_item("No knowledge artifacts available.")}
        """
    else:
        unknown_signal_summary = _to_dict(payload.get("unknown_signal_summary"))
        approval_summary = _to_dict(payload.get("approval_summary"))
        artifact_summary = _to_dict(payload.get("artifact_summary"))
        workflow_summary = _to_dict(payload.get("workflow_summary"))
        body = f"""
        <div class="governance-section-block">
          <h3>Unknown Signal Summary</h3>
          <div class="governance-summary-grid">
            {_render_memory_count_card("Total unknown signals observed", unknown_signal_summary.get("TOTAL"), "neutral")}
            {_render_memory_count_card("Total pending review", unknown_signal_summary.get("PENDING_REVIEW"), _parser_review_status_class("NEW"))}
            {_render_memory_count_card("Total approved", unknown_signal_summary.get("APPROVED"), _governance_approval_status_class("APPROVED"))}
            {_render_memory_count_card("Total rejected", unknown_signal_summary.get("REJECTED"), _governance_approval_status_class("REJECTED"))}
          </div>
        </div>
        <div class="governance-section-block">
          <h3>Knowledge Artifact Summary</h3>
          <p class="meta">Knowledge artifacts are visible for governance transparency only and are not active in runtime analysis.</p>
          <div class="governance-summary-grid">
            {_render_memory_count_card("Total governance artifacts", _governance_artifact_total(payload), "neutral")}
            {_render_memory_count_card("Total materialized artifacts", artifact_summary.get("MATERIALIZED"), "neutral")}
            {_render_memory_count_card("Total inactive artifacts", artifact_summary.get("INACTIVE"), _artifact_activation_status_class("INACTIVE"))}
            {_render_memory_count_card("Total pending requests", approval_summary.get("PENDING"), _governance_approval_status_class("PENDING"))}
          </div>
        </div>
        <div class="governance-section-block">
          <h3>Governance Workflow Status</h3>
          <div class="governance-summary-grid workflow-summary-grid">
            {_render_memory_count_card("NEW", workflow_summary.get("NEW"), _parser_review_status_class("NEW"))}
            {_render_memory_count_card("PENDING", workflow_summary.get("PENDING"), _governance_approval_status_class("PENDING"))}
            {_render_memory_count_card("APPROVED", workflow_summary.get("APPROVED"), _governance_approval_status_class("APPROVED"))}
            {_render_memory_count_card("REJECTED", workflow_summary.get("REJECTED"), _governance_approval_status_class("REJECTED"))}
            {_render_memory_count_card("NEEDS_REVISION", workflow_summary.get("NEEDS_REVISION"), _governance_approval_status_class("NEEDS_REVISION"))}
          </div>
        </div>
        <div class="governance-section-block">
          <h3>Run Linkage / Provenance</h3>
          {_render_governance_linkage_list(payload.get("linkage") or [])}
        </div>
        """
    return f"""
      <section class="card secondary governance-visibility-card">
        <div class="section-kicker">Phase 6 Governance</div>
        <h2>Governance & Knowledge Visibility</h2>
        <p class="meta">
          Governance records are read-only system memory. Approved requests and materialized artifacts do not change parser, scoring, recommendations, or runtime decisions until a future controlled activation phase.
          Interactive approval and governance workflows will be introduced in a future control-plane interface.
        </p>
        {body}
        <p class="meta">
          Governance memory, approvals, and knowledge artifacts are informational only and do not alter parser extraction, scoring, recommendations, or runtime decision behavior.
        </p>
      </section>
    """


def _render_semantic_recall_visibility_section(payload: dict[str, Any]) -> str:
    enabled = bool(payload.get("enabled"))
    status_tone = "success" if enabled else "neutral"
    status_text = "enabled" if enabled else "disabled"
    latest_context = payload.get("latest_context") or []
    latest_context_html = (
        _render_semantic_context_summary(latest_context)
        if latest_context
        else _render_empty_item(
            "No live semantic context is queried during dashboard generation. Semantic context, not diagnostic evidence, remains available only through optional reviewer-assist flows when configured."
        )
    )
    return f"""
      <section class="card secondary semantic-recall-card">
        <div class="section-kicker">Phase 6 Semantic Memory</div>
        <h2>Semantic Recall Visibility</h2>
        <p class="meta">
          Semantic recall provides optional analyst and reviewer context from curated Oracle Agent Memory entries. It is non-authoritative and does not alter parser, scoring, recommendations, approvals, or runtime decisions.
        </p>
        <div class="governance-section-block">
          <h3>Semantic Recall Status</h3>
          {_render_info_grid(
              [
                  ("Status", _TrustedHtml(f'<span class="mini-pill {status_tone}">{escape(status_text)}</span>')),
                  ("Provider", payload.get("provider")),
                  ("Mode", payload.get("mode")),
                  ("Authoritative", str(bool(payload.get("authoritative"))).lower()),
                  ("Runtime influence", str(bool(payload.get("runtime_influence"))).lower()),
              ],
              extra_class="semantic-recall-status-grid",
          )}
          <p class="meta semantic-status-message">{escape(_memory_cell_text(payload.get("status_message")))}</p>
        </div>
        <div class="governance-section-block">
          <h3>Semantic Assist Scope</h3>
          {_render_semantic_assist_scope(payload.get("assist_scope") or [])}
        </div>
        <div class="governance-section-block">
          <h3>Optional Latest Semantic Context</h3>
          <p class="meta">Semantic context, not diagnostic evidence.</p>
          {latest_context_html}
        </div>
        <p class="meta semantic-boundary-notice">
          Semantic recall is reviewer-assist context only. It does not change deterministic diagnosis, scoring, recommendations, governance approvals, artifact activation, or dashboard truth.
        </p>
      </section>
    """


def _render_learning_visibility_section(payload: dict[str, Any]) -> str:
    display_payload = payload or build_learning_visibility_metadata()
    candidate_count = int(display_payload.get("candidate_count") or 0)
    governance = _to_dict(display_payload.get("governance"))
    governance_records = list(governance.get("records") or [])
    empty_state_html = ""
    if candidate_count == 0:
        empty_state_html = _render_learning_empty_state(
            display_payload.get("empty_state_messages") or []
        )

    return f"""
      <section class="card secondary learning-visibility-card">
        <div class="section-kicker">Phase 7G Learning Visibility</div>
        <h2>Learning Visibility</h2>
        <p class="meta">
          Learning Visibility is Read-only. Learning candidates are proposed / review-state records only. Human review required; runtime_influence=false; requires_human_review=true. Not diagnostic evidence. Not recommendation truth. Not automatically applied.
        </p>
        <div class="governance-section-block">
          <h3>Read-only Boundary</h3>
          {_render_learning_safety_labels(display_payload.get("safety_labels") or [])}
        </div>
        {empty_state_html}
        <div class="governance-section-block">
          <h3>Candidate Summary</h3>
          {_render_learning_summary(display_payload)}
        </div>
        <div class="governance-section-block">
          <h3>Top Proposed Candidates</h3>
          {_render_learning_candidate_rows(display_payload.get("candidates") or [])}
        </div>
        <div class="governance-section-block">
          <h3>Governance Bridge Review State</h3>
          {_render_learning_governance_rows(governance_records)}
        </div>
        <p class="meta learning-boundary-notice">
          Approved for implementation only, not runtime activation. Governance approval is not runtime activation. Semantic context is reviewer-assist only and is not source_evidence, not diagnostic evidence, and not recommendation truth. Full dashboard interactivity remains future Phase 7H.
        </p>
      </section>
    """


def _render_learning_empty_state(messages: list[Any]) -> str:
    rendered = [
        _render_empty_item(_memory_cell_text(message))
        for message in messages
        if _has_display_value(message)
    ]
    if not rendered:
        rendered = [
            _render_empty_item("No learning candidates available"),
            _render_empty_item("Learning visibility is read-only"),
            _render_empty_item("No runtime influence"),
        ]
    return '<div class="learning-empty-state">' + "".join(rendered) + "</div>"


def _render_learning_safety_labels(labels: list[Any]) -> str:
    rendered = [
        f'<span class="mini-pill neutral">{escape(_memory_cell_text(label))}</span>'
        for label in labels
        if _has_display_value(label)
    ]
    if not rendered:
        rendered = [
            '<span class="mini-pill neutral">Read-only</span>',
            '<span class="mini-pill neutral">runtime_influence=false</span>',
        ]
    return '<div class="mini-pill-group learning-safety-labels">' + "".join(rendered) + "</div>"


def _render_learning_summary(payload: dict[str, Any]) -> str:
    status_counts = _to_dict(payload.get("status_counts"))
    type_counts = _to_dict(payload.get("type_counts"))
    component_counts = _to_dict(payload.get("affected_component_counts"))
    domain_counts = _to_dict(payload.get("affected_domain_counts"))
    summary_parts = [
        _render_memory_count_card("Total candidates", payload.get("candidate_count"), "neutral"),
        _render_memory_count_card("Semantic context present", payload.get("semantic_context_count"), "neutral"),
        _render_memory_count_card("runtime_influence=false", 1, "success"),
        _render_memory_count_card("requires_human_review=true", 1, "warning"),
    ]
    for label, count in status_counts.items():
        summary_parts.append(
            _render_memory_count_card(
                f"Status {label}",
                count,
                _learning_status_class(label),
            )
        )
    for label, count in type_counts.items():
        summary_parts.append(_render_memory_count_card(f"Type {label}", count, "neutral"))
    for label, count in component_counts.items():
        summary_parts.append(_render_memory_count_card(f"Component {label}", count, "neutral"))
    for label, count in domain_counts.items():
        summary_parts.append(_render_memory_count_card(f"Domain {label}", count, "neutral"))
    return '<div class="governance-summary-grid learning-summary-grid">' + "".join(summary_parts) + "</div>"


def _render_learning_candidate_rows(candidates: list[Any]) -> str:
    rows = [_to_dict(candidate) for candidate in candidates]
    if not rows:
        return _render_empty_item("No learning candidates available")
    rendered_rows = []
    for row in rows[:5]:
        status = _memory_cell_text(row.get("status"))
        semantic_label = (
            "semantic_context present - Semantic context is reviewer-assist only"
            if bool(row.get("semantic_context_present"))
            else "semantic_context absent"
        )
        materialization = row.get("materialization_reference_label") or "—"
        rendered_rows.append(
            f"""
            <article class="learning-candidate-row">
              <div>
                <strong>{escape(_memory_cell_text(row.get("candidate_id")))}</strong>
                <span>{escape(_memory_cell_text(row.get("title")))}</span>
              </div>
              <div>{escape(_memory_cell_text(row.get("candidate_type")))}</div>
              <div><span class="mini-pill {escape(_learning_status_class(status))}">{escape(status)}</span></div>
              <div>{escape(_memory_cell_text(row.get("affected_component")))}</div>
              <div>{escape(_memory_cell_text(row.get("affected_domain")))}</div>
              <div>{escape(_learning_confidence_text(row.get("confidence")))}</div>
              <div>
                <span>requires_human_review=true</span>
                <span>runtime_influence=false</span>
              </div>
              <div>
                <span>source evidence count: {escape(_memory_cell_text(row.get("source_evidence_count")))}</span>
                <span>{escape(semantic_label)}</span>
              </div>
              <div>{escape(_memory_cell_text(materialization))}</div>
            </article>
            """
        )
    return f"""
        <div class="learning-candidate-list">
          <div class="learning-candidate-row learning-candidate-header">
            <div>candidate_id / title</div>
            <div>candidate_type</div>
            <div>status</div>
            <div>affected_component</div>
            <div>affected_domain</div>
            <div>confidence</div>
            <div>safety</div>
            <div>source / semantic</div>
            <div>materialization_reference</div>
          </div>
          {"".join(rendered_rows)}
        </div>
    """


