def _screen6_pattern_items(
    raw_items: Any,
    *,
    select_type: str,
    state_key: str,
    default_label: str,
    note: str,
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for index, raw_item in enumerate(_screen6_list(raw_items)):
        item = _to_dict(raw_item) if isinstance(raw_item, dict) else {}
        label = (
            item.get("pattern_id")
            or item.get("id")
            or item.get("title")
            or item.get("label")
            or item.get("pattern_type")
            or raw_item
            or f"{default_label} {index + 1}"
        )
        if not _has_display_value(label):
            continue
        _append_screen6_selector_item(
            items,
            label=label,
            value=f"{_screen6_state_id(select_type)}-{index + 1}-{_screen6_state_id(label)}",
            select_type=select_type,
            state_key=state_key,
            domain=_screen6_selector_domain(item.get("domain") or item.get("affected_domain") or label),
            display_value=item.get("summary") or item.get("description") or item.get("count") or raw_item,
            note=note,
        )
    return items


def _screen6_first_context_collection(
    screen_model: dict[str, Any],
    learning_visibility_payload: dict[str, Any],
    keys: tuple[str, ...],
) -> Any:
    for source in (screen_model, learning_visibility_payload):
        for key in keys:
            value = source.get(key)
            if value:
                return value
    return []


def _screen6_list(value: Any) -> list[Any]:
    if not value:
        return []
    if isinstance(value, list):
        return value
    if isinstance(value, tuple):
        return list(value)
    if isinstance(value, set):
        return sorted(value)
    if isinstance(value, dict):
        for key in ("items", "records", "contexts", "patterns", "values"):
            if isinstance(value.get(key), list):
                return list(value.get(key) or [])
        return [value]
    return [value]


def _append_screen6_selector_item(
    items: list[dict[str, Any]],
    *,
    label: Any,
    value: Any,
    select_type: str,
    state_key: str,
    display_value: Any = None,
    note: Any = None,
    domain: Any = None,
) -> None:
    if not _has_display_value(label) or not _has_display_value(value):
        return
    domain_text = _screen6_selector_domain(domain)
    items.append(
        {
            "label": _display_value(label),
            "value": _display_value(value),
            "select_type": select_type,
            "state_key": state_key,
            "display_value": _display_value(display_value) if _has_display_value(display_value) else "",
            "note": _display_value(note) if _has_display_value(note) else "",
            "domain": domain_text or "",
        }
    )


def _render_screen6_selector_group(
    title: str,
    description: str,
    items: list[dict[str, Any]],
    empty_message: str,
) -> str:
    if not items:
        return f"""
          <section class="evidence-pane selector-pane">
            <h3>{escape(title)}</h3>
            <p class="meta">{escape(description)}</p>
            <div class="item">
              <p>{escape(empty_message)}</p>
            </div>
          </section>
        """
    cards = "".join(_render_screen6_selector_card(item) for item in items)
    return f"""
          <section class="evidence-pane selector-pane">
            <h3>{escape(title)}</h3>
            <p class="meta">{escape(description)}</p>
            <div class="screen6-selector-grid">{cards}</div>
          </section>
    """


def _render_screen6_selector_card(item: dict[str, Any]) -> str:
    select_type = _display_value(item.get("select_type"))
    state_key = _display_value(item.get("state_key"))
    value = _display_value(item.get("value"))
    domain = _display_value(item.get("domain")) if _has_display_value(item.get("domain")) else ""
    domain_attribute = (
        f' data-dashboard-select-domain="{escape(domain, quote=True)}"'
        if domain
        else ""
    )
    return f"""
              <article
                class="screen6-selector-card"
                data-dashboard-selectable="true"
                data-dashboard-select-type="{escape(select_type, quote=True)}"
                data-dashboard-select-key="{escape(state_key, quote=True)}"
                data-dashboard-select-id="{escape(value, quote=True)}"
                data-dashboard-filter-key="{escape(state_key, quote=True)}"
                data-dashboard-filter-value="{escape(value, quote=True)}"{domain_attribute}
                data-selected="false"
                aria-selected="false"
                tabindex="0"
              >
                <strong>{escape(select_type.replace("-", " ").title())}</strong>
                <span>{escape(_display_value(item.get("label")))}</span>
                {
                    f'<p>{escape(_display_value(item.get("display_value")))}</p>'
                    if _has_display_value(item.get("display_value"))
                    else ""
                }
                {
                    f'<p>{escape(_display_value(item.get("note")))}</p>'
                    if _has_display_value(item.get("note"))
                    else ""
                }
              </article>
    """


def _screen6_selector_domain(value: Any) -> str | None:
    text = str(value or "").strip().upper()
    if not text:
        return None
    if "USER I/O" in text or "USER IO" in text:
        return "IO"
    if "LOG FILE" in text or "COMMIT" in text or "TRANSACTION" in text:
        return "COMMIT"
    if "CLUSTER" in text or "GC " in text or "RAC" in text:
        return "RAC"
    if "DATA GUARD" in text or "TRANSPORT" in text or "APPLY LAG" in text or "ADG" in text:
        return "ADG"
    if "PGA" in text or "MEMORY" in text or "TEMP" in text:
        return "MEMORY"
    if "CPU" in text or "SQL" in text:
        return "CPU"
    if "IO" in text or "I/O" in text:
        return "IO"
    for domain in SCREEN6_FLEET_GOVERNANCE_LEARNING_DOMAINS:
        if domain in text:
            return domain
    return None


def _screen6_state_id(value: Any) -> str:
    text = re.sub(r"[^a-zA-Z0-9]+", "-", _display_value(value).strip().lower())
    return text.strip("-")[:80] or "selection"


def _dedupe_screen6_selector_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[tuple[str, str]] = set()
    deduped: list[dict[str, Any]] = []
    for item in items:
        key = (_display_value(item.get("state_key")), _display_value(item.get("value")))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped


def _render_screen_6_page(
    screen_model: dict[str, Any],
    governance_payload: dict[str, Any] | None = None,
    semantic_recall_payload: dict[str, Any] | None = None,
    learning_visibility_payload: dict[str, Any] | None = None,
    ml_explainability_visibility_payload: dict[str, Any] | None = None,
) -> str:
    header = _to_dict(screen_model.get("header"))
    fleet_summary = _to_dict(screen_model.get("fleet_summary"))
    clusters = _to_dict(screen_model.get("clusters"))
    rare_patterns = _to_dict(screen_model.get("rare_patterns"))
    anomaly_validation = _to_dict(screen_model.get("anomaly_validation"))
    repeated_issues = list(screen_model.get("repeated_issues") or [])
    recommendation_backlog = list(screen_model.get("recommendation_backlog") or [])
    outliers = list(screen_model.get("outliers") or [])
    similar_cases = list(clusters.get("similar_cases") or [])
    cluster_label = _display_cluster_label(fleet_summary.get("cluster_label"))
    cluster_confidence = _safe_float(fleet_summary.get("cluster_confidence")) or 0.0
    cluster_established = (
        cluster_label != "No stable similarity cluster has been established for this dataset."
        and cluster_confidence > 0.0
    )
    summary_title = (
        "Similarity Fleet Summary"
        if cluster_established
        else "Nearest Similar AWRs"
    )
    governance_display_payload = governance_payload or {}
    semantic_display_payload = semantic_recall_payload or {}
    learning_display_payload = learning_visibility_payload or build_learning_visibility_metadata()
    ml_display_payload = (
        ml_explainability_visibility_payload
        or build_ml_explainability_visibility_metadata()
    )
    screen6_exploration_html = _render_screen6_fleet_governance_learning_exploration(
        screen_model,
        governance_display_payload,
        semantic_display_payload,
        learning_display_payload,
    )
    screen6_candidate_review_html = _render_screen6_candidate_review_preview_panel(
        learning_display_payload
    )
    screen6_materialization_review_html = _render_screen6_materialization_review_preview_panel(
        governance_display_payload
    )
    screen6_model_registry_review_html = _render_screen6_model_registry_review_preview_panel(
        ml_display_payload
    )
    screen6_runtime_gate_review_html = _render_screen6_runtime_gate_review_preview_panel(
        ml_display_payload
    )
    if not screen_model.get("similarity_enabled") and not similar_cases:
        return f"""
    <div class="grid">
      <!-- Screen 6 = learning governance, materialization review, runtime eligibility, and supporting fleet context. -->
      <section class="card prominent">
        <div class="section-kicker">Screen 6</div>
        <h2>Learning Governance</h2>
        {_render_info_grid(
            [
                ("Scope", header.get("scope_label")),
                ("DB / DBID", _join_compact_values([header.get("db_name"), header.get("dbid")])),
                ("Snapshot Count", header.get("snapshot_count")),
                ("Comparison Window", header.get("comparison_window")),
            ]
        )}
      </section>
      <section class="card prominent">
        <div class="section-kicker">Fleet Intelligence</div>
        <h2>Fleet intelligence unavailable — DB connection failed or was not checked.</h2>
        <p class="meta">
          Local analysis is available on Screens 1-5. Start the database and rerun analysis
          to enable AWR reuse, feature-vector lookup, similarity, and fleet intelligence.
        </p>
      </section>
      {screen6_exploration_html}
      {screen6_candidate_review_html}
      {screen6_materialization_review_html}
      {screen6_model_registry_review_html}
      {screen6_runtime_gate_review_html}
      {_render_governance_visibility_section(governance_display_payload)}
      {_render_semantic_recall_visibility_section(semantic_display_payload)}
      {_render_learning_visibility_section(learning_display_payload)}
      {_render_ml_explainability_visibility_section(ml_display_payload)}
    </div>
    """
    return f"""
    <div class="grid">
      <!-- Screen 6 = learning governance, materialization review, runtime eligibility, and supporting fleet context. -->
      <section class="card prominent">
        <div class="section-kicker">Screen 6</div>
        <h2>Learning Governance Context Preview</h2>
        <p class="meta fleet-preview-note">
          Nearest-neighbor similarity is informative only; validated fleet patterns require more distinct historical cases.
        </p>
        {_render_info_grid(
            [
                ("Scope", header.get("scope_label")),
                ("DB / DBID", _join_compact_values([header.get("db_name"), header.get("dbid")])),
                ("Snapshot Count", header.get("snapshot_count")),
                ("Comparison Window", header.get("comparison_window")),
            ]
        )}
      </section>
      <section class="card secondary fleet-compact-card">
        <div class="section-kicker">Fleet Summary</div>
        <h2>{escape(summary_title)}</h2>
        <p class="meta">Similarity is informative only and does not override deterministic diagnosis.</p>
        {_render_fleet_summary_strip(
            [
                ("Similar AWRs", fleet_summary.get("similar_awrs")),
                ("Cluster", _display_cluster_summary_label(fleet_summary.get("cluster_label"))),
                ("Rarity", _display_rarity_summary_label(fleet_summary.get("rarity"))),
                ("Repeated Issues", _repeated_issue_compact_label(repeated_issues)),
                ("Backlog", _recommendation_backlog_compact_label(recommendation_backlog)),
            ]
        )}
      </section>
      <section class="card secondary">
        <h2>Nearest Similar AWRs</h2>
        <p class="meta">These are nearest-neighbor AWR cases from vector similarity, not validated workload clusters.</p>
        {_render_similarity_cases(similar_cases)}
      </section>
      <section class="card secondary fleet-compact-card">
        <h2>Fleet Signal Details</h2>
        {_render_fleet_detail_list(
            [
                ("Rare Pattern", rare_patterns.get("is_rare_pattern")),
                ("Nearest Distance", rare_patterns.get("nearest_distance")),
                ("Mean Distance", rare_patterns.get("mean_distance")),
                ("Anomaly Support", anomaly_validation.get("supports_anomaly")),
                ("Similar Case Count", anomaly_validation.get("similar_case_count")),
                ("Cluster Confidence", cluster_confidence if cluster_established else None),
                ("Recommendation Backlog", _recommendation_backlog_compact_label(recommendation_backlog)),
                ("Reason", anomaly_validation.get("reason") or rare_patterns.get("reason")),
            ]
        )}
        {_render_similarity_cases(outliers) if outliers else _render_empty_item("No outlier case aggregation is established yet.")}
      </section>
      {screen6_exploration_html}
      {screen6_candidate_review_html}
      {screen6_materialization_review_html}
      {screen6_model_registry_review_html}
      {screen6_runtime_gate_review_html}
      {_render_governance_visibility_section(governance_display_payload)}
      {_render_semantic_recall_visibility_section(semantic_display_payload)}
      {_render_learning_visibility_section(learning_display_payload)}
      {_render_ml_explainability_visibility_section(ml_display_payload)}
    </div>
    """


